import { FC, useState, useEffect } from 'react';
import GlassCard from '@/components/ui/GlassCard';
import { useJobTimer } from '@/hooks/useJobTimer';
import { Bar } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend
} from 'chart.js';

// Register the chart.js components
ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend
);

interface JobMetric {
  title: string;
  value: string;
  icon: string;
  color: string;
}

const JobInsights: FC = () => {
  const { currentJob, hourlyRate, time } = useJobTimer();
  
  // Parse time string (e.g. "02:45:30") to minutes worked
  const timeToMinutes = (timeString: string): number => {
    const [hours, minutes] = timeString.split(':').map(Number);
    return (hours * 60) + minutes;
  };
  
  const minutesWorked = timeToMinutes(time);
  
  // Job performance metrics
  const [metrics, setMetrics] = useState<JobMetric[]>([
    {
      title: 'Productivity',
      value: '87%',
      icon: 'fa-rocket',
      color: 'text-blue-400'
    },
    {
      title: 'Billable Rate',
      value: `$${hourlyRate.toFixed(2)}/hr`,
      icon: 'fa-dollar-sign',
      color: 'text-green-400'
    },
    {
      title: 'Time Efficiency',
      value: '92%',
      icon: 'fa-tachometer-alt',
      color: 'text-purple-400'
    },
    {
      title: 'Completion',
      value: '48%',
      icon: 'fa-chart-pie',
      color: 'text-yellow-400'
    }
  ]);
  
  // Update metrics when hourly rate changes
  useEffect(() => {
    setMetrics(prev => {
      const updated = [...prev];
      updated[1].value = `$${hourlyRate.toFixed(2)}/hr`;
      return updated;
    });
  }, [hourlyRate]);
  
  // Mock data for previous days' time tracking
  const chartData = {
    labels: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Today'],
    datasets: [
      {
        label: 'Hours Worked',
        data: [3.5, 4.2, 2.8, 5.1, 3.7, minutesWorked / 60],
        backgroundColor: 'rgba(0, 240, 200, 0.5)',
        borderColor: 'rgba(0, 240, 200, 1)',
        borderWidth: 2,
        borderRadius: 6,
        hoverBackgroundColor: 'rgba(0, 240, 200, 0.7)'
      }
    ]
  };
  
  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        display: false
      },
      tooltip: {
        backgroundColor: 'rgba(12, 14, 26, 0.8)',
        titleColor: '#00f0c8',
        bodyColor: '#ffffff',
        borderColor: 'rgba(0, 240, 200, 0.3)',
        borderWidth: 1,
        padding: 10,
        displayColors: false,
        callbacks: {
          label: function(context: any) {
            return `${context.parsed.y.toFixed(1)} hours`;
          }
        }
      }
    },
    scales: {
      y: {
        beginAtZero: true,
        grid: {
          color: 'rgba(255, 255, 255, 0.05)'
        },
        ticks: {
          color: 'rgba(255, 255, 255, 0.7)'
        }
      },
      x: {
        grid: {
          display: false
        },
        ticks: {
          color: 'rgba(255, 255, 255, 0.7)'
        }
      }
    }
  };
  
  // Mock data for project tasks
  const tasks = [
    { name: 'Foundation Work', complete: true },
    { name: 'Plumbing Installation', complete: true },
    { name: 'Electrical Wiring', complete: false },
    { name: 'Interior Walls', complete: false },
    { name: 'Final Inspection', complete: false }
  ];
  
  // Mock recommendation based on current progress
  const recommendations = [
    { text: 'Work at this pace consistently to complete the project 2 days ahead of schedule', icon: 'fa-bolt', color: 'text-teal' },
    { text: 'Consider allocating more time to electrical wiring as it may require additional attention', icon: 'fa-lightbulb', color: 'text-yellow-400' }
  ];
  
  const [activeTab, setActiveTab] = useState<'analytics' | 'tasks' | 'recommendations'>('analytics');
  
  return (
    <GlassCard 
      className="rounded-xl overflow-hidden mb-6 p-0" 
      variant="teal"
      glow={true}
      blur="lg"
    >
      {/* Header with tabs */}
      <div className="flex justify-between items-center px-5 py-4 border-b border-teal/20">
        <div className="flex items-center space-x-1.5">
          <h3 className="text-lg font-space text-teal mr-2">Job Insights</h3>
          <div className="flex bg-space-900/70 rounded-lg p-0.5">
            <button 
              className={`px-3 py-1 text-xs rounded-md transition-all duration-200 ${activeTab === 'analytics' ? 'bg-teal/30 text-white shadow-inner' : 'text-gray-300 hover:text-white'}`}
              onClick={() => setActiveTab('analytics')}
            >
              <i className="fas fa-chart-bar mr-1.5"></i>Analytics
            </button>
            <button 
              className={`px-3 py-1 text-xs rounded-md transition-all duration-200 ${activeTab === 'tasks' ? 'bg-teal/30 text-white shadow-inner' : 'text-gray-300 hover:text-white'}`}
              onClick={() => setActiveTab('tasks')}
            >
              <i className="fas fa-tasks mr-1.5"></i>Tasks
            </button>
            <button 
              className={`px-3 py-1 text-xs rounded-md transition-all duration-200 ${activeTab === 'recommendations' ? 'bg-teal/30 text-white shadow-inner' : 'text-gray-300 hover:text-white'}`}
              onClick={() => setActiveTab('recommendations')}
            >
              <i className="fas fa-magic mr-1.5"></i>Insights
            </button>
          </div>
        </div>
        <div>
          <button className="text-teal hover:text-cyan transition-colors">
            <i className="fas fa-expand-alt"></i>
          </button>
        </div>
      </div>
      
      {/* Content area */}
      <div className="p-5">
        {activeTab === 'analytics' && (
          <div>
            {/* Key metrics */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-5">
              {metrics.map((metric, index) => (
                <div key={index} className="bg-space-900/40 rounded-lg p-3 backdrop-blur-sm">
                  <div className="flex items-center space-x-3">
                    <div className={`${metric.color} bg-space-800 h-10 w-10 rounded-full flex items-center justify-center`}>
                      <i className={`fas ${metric.icon}`}></i>
                    </div>
                    <div>
                      <div className="text-sm text-gray-400">{metric.title}</div>
                      <div className="text-white font-medium text-lg">{metric.value}</div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
            
            {/* Chart */}
            <div className="bg-space-900/40 rounded-lg p-4 backdrop-blur-sm">
              <h4 className="text-sm font-medium text-white mb-2">Time Tracking</h4>
              <div className="h-48 overflow-hidden">
                <Bar data={chartData} options={chartOptions} />
              </div>
            </div>
          </div>
        )}
        
        {activeTab === 'tasks' && (
          <div className="bg-space-900/40 rounded-lg p-4 backdrop-blur-sm">
            <div className="flex justify-between items-center mb-3">
              <h4 className="text-sm font-medium text-white">Project Tasks</h4>
              <div className="text-xs bg-teal/20 text-teal px-2 py-1 rounded-full">
                {tasks.filter(t => t.complete).length}/{tasks.length} Complete
              </div>
            </div>
            
            <div className="space-y-2">
              {tasks.map((task, index) => (
                <div key={index} className="flex items-center py-2 border-b border-space-700/30">
                  <div className={`h-5 w-5 rounded-full border ${task.complete ? 'bg-teal border-teal' : 'border-gray-500'} mr-3 flex items-center justify-center text-xs`}>
                    {task.complete && <i className="fas fa-check text-black"></i>}
                  </div>
                  <span className={`${task.complete ? 'text-white line-through opacity-70' : 'text-white'}`}>
                    {task.name}
                  </span>
                  {!task.complete && (
                    <button className="ml-auto text-teal hover:text-cyan-300 transition-colors">
                      <i className="fas fa-play-circle"></i>
                    </button>
                  )}
                </div>
              ))}
            </div>
            
            <button className="mt-4 bg-teal/20 hover:bg-teal/30 text-teal px-3 py-1.5 rounded-md text-sm transition-colors w-full">
              <i className="fas fa-plus mr-1.5"></i>Add New Task
            </button>
          </div>
        )}
        
        {activeTab === 'recommendations' && (
          <div>
            <div className="bg-space-900/40 rounded-lg p-4 backdrop-blur-sm mb-4">
              <h4 className="text-sm font-medium text-white mb-3">AI Recommendations</h4>
              
              <div className="space-y-3">
                {recommendations.map((rec, index) => (
                  <div key={index} className="flex space-x-3 items-start p-3 bg-space-800/50 rounded-lg border-l-2 border-teal/50">
                    <div className={`${rec.color} mt-0.5`}>
                      <i className={`fas ${rec.icon} text-lg`}></i>
                    </div>
                    <p className="text-white text-sm">{rec.text}</p>
                  </div>
                ))}
              </div>
            </div>
            
            <div className="bg-space-900/40 rounded-lg p-4 backdrop-blur-sm">
              <h4 className="text-sm font-medium text-white mb-3">Job Performance</h4>
              
              <div className="relative pt-1">
                <div className="flex items-center justify-between mb-2">
                  <div>
                    <span className="text-xs font-medium text-gray-400">Overall Completion</span>
                  </div>
                  <div className="text-right">
                    <span className="text-xs font-medium text-teal">48%</span>
                  </div>
                </div>
                <div className="overflow-hidden h-2 text-xs flex rounded-full bg-space-800">
                  <div style={{ width: "48%" }} className="shadow-none flex flex-col text-center whitespace-nowrap text-white justify-center bg-gradient-to-r from-teal/80 to-teal"></div>
                </div>
                
                <div className="flex items-center justify-between mt-4 mb-2">
                  <div>
                    <span className="text-xs font-medium text-gray-400">Budget Used</span>
                  </div>
                  <div className="text-right">
                    <span className="text-xs font-medium text-blue-400">32%</span>
                  </div>
                </div>
                <div className="overflow-hidden h-2 text-xs flex rounded-full bg-space-800">
                  <div style={{ width: "32%" }} className="shadow-none flex flex-col text-center whitespace-nowrap text-white justify-center bg-gradient-to-r from-blue-500/80 to-blue-400"></div>
                </div>
              </div>
              
              <div className="mt-6 flex justify-between">
                <div className="text-center">
                  <div className="text-xs text-gray-400 mb-1">ESTIMATED</div>
                  <div className="text-lg font-medium text-white">$5,280</div>
                  <div className="text-xs text-gray-400">TOTAL</div>
                </div>
                <div className="text-center">
                  <div className="text-xs text-gray-400 mb-1">ACTUAL</div>
                  <div className="text-lg font-medium text-white">$1,692</div>
                  <div className="text-xs text-teal">UNDER BUDGET</div>
                </div>
                <div className="text-center">
                  <div className="text-xs text-gray-400 mb-1">ESTIMATED</div>
                  <div className="text-lg font-medium text-white">May 30</div>
                  <div className="text-xs text-teal">ON SCHEDULE</div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
      
      {/* Footer */}
      <div className="bg-space-900/60 p-3 border-t border-teal/10 flex justify-between items-center">
        <div className="text-xs text-gray-400">
          <span className="text-teal mr-1"><i className="fas fa-sync-alt fa-spin-pulse"></i></span>
          Updated just now
        </div>
        <div>
          <button className="bg-teal/20 hover:bg-teal/30 text-teal px-3 py-1 rounded-md text-xs transition-colors">
            <i className="fas fa-chart-line mr-1.5"></i>Detailed Report
          </button>
        </div>
      </div>
    </GlassCard>
  );
};

export default JobInsights;
