import { FC, useState } from 'react';
import GlassCard from '@/components/ui/GlassCard';
import { useWeather } from '@/hooks/useWeather';

// Project types for weather impact analysis
const projectTypes = [
  "Residential New Build",
  "Commercial Construction",
  "Road Construction",
  "Exterior Painting",
  "Roofing",
  "Concrete Pouring"
];

const WeatherWidget: FC = () => {
  const { 
    currentWeather, 
    forecast, 
    location,
    weatherImpact,
    detailedImpact,
    availableLocations,
    isLoading,
    updateLocation,
    generateWeatherImpactAnalysis
  } = useWeather();
  
  const [isExpanded, setIsExpanded] = useState(false);
  const [showLocationDropdown, setShowLocationDropdown] = useState(false);
  const [showAnalysisOptions, setShowAnalysisOptions] = useState(false);
  const [selectedProjectType, setSelectedProjectType] = useState(projectTypes[0]);
  const [analysisResult, setAnalysisResult] = useState('');
  
  const handleLocationChange = (newLocation: string) => {
    updateLocation(newLocation);
    setShowLocationDropdown(false);
  };
  
  const handleGenerateAnalysis = async () => {
    const result = await generateWeatherImpactAnalysis(selectedProjectType);
    setAnalysisResult(result);
    setShowAnalysisOptions(false);
  };
  
  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'low': return 'bg-green-800/50 text-green-400';
      case 'medium': return 'bg-yellow-800/50 text-yellow-400';
      case 'high': return 'bg-red-800/50 text-red-400';
      default: return 'bg-cyan-800/50 text-cyan-400';
    }
  };
  
  return (
    <GlassCard className={`p-4 transition-all duration-300 weather-widget ${isExpanded ? 'col-span-2 row-span-2' : ''}`}>
      <div className="flex justify-between items-start mb-3">
        <h3 className="text-md font-space text-white">Weather Impact</h3>
        <div className="flex gap-2">
          <button 
            onClick={() => setIsExpanded(!isExpanded)} 
            className="text-teal hover:text-cyan transition-colors"
          >
            <i className={`fas ${isExpanded ? 'fa-compress-alt' : 'fa-expand-alt'}`}></i>
          </button>
          <span className="text-teal"><i className="fas fa-cloud-sun"></i></span>
        </div>
      </div>
      
      <div className="relative">
        <div 
          className="flex items-center mb-3 cursor-pointer" 
          onClick={() => setShowLocationDropdown(!showLocationDropdown)}
        >
          <div className="text-4xl text-teal mr-3">
            <i className={`fas ${currentWeather.icon}`}></i>
          </div>
          <div className="flex-1">
            <div className="text-xl font-medium text-white flex items-center">
              {location}
              <i className="fas fa-caret-down ml-2 text-sm text-gray-400"></i>
            </div>
            <div className="text-sm text-gray-400">{currentWeather.description}</div>
          </div>
          <div className="text-2xl font-medium text-white">
            {currentWeather.temp}°C
          </div>
        </div>
        
        {showLocationDropdown && (
          <div className="absolute left-0 right-0 mt-1 z-10 bg-space-800 border border-gray-700 rounded-md shadow-lg max-h-48 overflow-y-auto">
            {availableLocations.map(loc => (
              <div 
                key={loc} 
                className="px-3 py-2 hover:bg-space-700 cursor-pointer text-white text-sm"
                onClick={() => handleLocationChange(loc)}
              >
                {loc}
              </div>
            ))}
          </div>
        )}
      </div>
      
      {/* Current Weather Details */}
      {isExpanded && (
        <div className="grid grid-cols-3 gap-2 mb-3">
          <div className="bg-space-900/50 rounded-lg p-2 text-center">
            <div className="text-xs text-gray-400">Humidity</div>
            <div className="text-sm text-white">{currentWeather.humidity}%</div>
          </div>
          <div className="bg-space-900/50 rounded-lg p-2 text-center">
            <div className="text-xs text-gray-400">Wind</div>
            <div className="text-sm text-white">{currentWeather.windSpeed} km/h {currentWeather.windDirection}</div>
          </div>
          <div className="bg-space-900/50 rounded-lg p-2 text-center">
            <div className="text-xs text-gray-400">UV Index</div>
            <div className="text-sm text-white">{currentWeather.uvIndex}</div>
          </div>
        </div>
      )}
      
      {/* Weather Impact */}
      <div 
        className={`py-2 px-3 mb-3 ${getSeverityColor(detailedImpact.severity)} rounded-lg cursor-pointer`}
        onClick={() => setShowAnalysisOptions(!showAnalysisOptions)}
      >
        <div className="flex justify-between items-center">
          <div className="text-sm font-medium mb-1">Site Work Impact</div>
          <div className="text-xs rounded px-2 py-0.5 bg-space-900/80">
            {detailedImpact.severity.toUpperCase()}
          </div>
        </div>
        <div className="text-sm text-white">{weatherImpact}</div>
        
        {isExpanded && (
          <div className="mt-2 text-xs text-white/80">
            <div className="font-medium mb-1">Affected Sites:</div>
            <ul className="list-disc list-inside">
              {detailedImpact.affectedSites.map((site, idx) => (
                <li key={idx}>{site}</li>
              ))}
            </ul>
            
            <div className="font-medium mt-2 mb-1">Material Impacts:</div>
            <div className="grid grid-cols-2 gap-1">
              {detailedImpact.materialImpacts.map((impact, idx) => (
                <div key={idx} className="bg-space-900/30 rounded p-1">
                  <span className="font-medium">{impact.type}:</span> {impact.effect}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
      
      {/* Analysis Options */}
      {showAnalysisOptions && (
        <div className="mb-3 p-3 bg-space-900/50 rounded-lg">
          <div className="text-sm font-medium text-white mb-2">Generate Impact Analysis</div>
          <div className="flex flex-col space-y-2">
            <select
              value={selectedProjectType}
              onChange={(e) => setSelectedProjectType(e.target.value)}
              className="w-full bg-space-800 text-white border border-gray-700 rounded p-2 text-sm"
            >
              {projectTypes.map(type => (
                <option key={type} value={type}>{type}</option>
              ))}
            </select>
            <button
              onClick={handleGenerateAnalysis}
              disabled={isLoading}
              className="w-full bg-purple-900 text-cyan py-1.5 px-3 rounded hover:bg-purple-800 text-sm"
            >
              {isLoading ? 'Generating...' : 'Analyze Weather Impact'}
            </button>
          </div>
        </div>
      )}
      
      {/* Analysis Result */}
      {analysisResult && isExpanded && (
        <div className="mb-3 p-3 bg-space-900/50 rounded-lg max-h-40 overflow-y-auto">
          <div className="text-sm font-medium text-cyan mb-1">Weather Impact Analysis</div>
          <div className="text-xs text-white whitespace-pre-line">{analysisResult}</div>
        </div>
      )}
      
      {/* Forecast */}
      <div className="flex justify-between overflow-x-auto">
        {forecast.map((day, index) => (
          <div key={index} className="text-center flex-1 min-w-[60px]">
            <div className="text-xs text-gray-400">{day.day}</div>
            <div className="text-lg text-white">{day.temp}°C</div>
            <div className="text-xs"><i className={`fas ${day.icon}`}></i></div>
            {isExpanded && (
              <>
                <div className="text-xs text-gray-400 mt-1">{day.conditions}</div>
                <div className="text-xs text-gray-400">{day.windSpeed} km/h</div>
              </>
            )}
          </div>
        ))}
      </div>
    </GlassCard>
  );
};

export default WeatherWidget;
