import { FC, useState, useEffect } from 'react';
import { Shield, BarChart2, Users, CreditCard, Server, Settings } from 'lucide-react';
import { useLocation } from 'wouter';
import { useAuth } from '../hooks/useAuth';
import SimpleSystemSettings from '../components/admin/SimpleSystemSettings';
import AdminDashboard from '../components/admin/dashboard/AdminDashboard';
import UserManagement from '../components/admin/users/UserManagement';
import SubscriptionManagement from '../components/admin/subscriptions/SubscriptionManagement';
import SystemMaintenance from '../components/admin/maintenance/SystemMaintenance';

const Admin: FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const { user } = useAuth();
  const [, setLocation] = useLocation();
  
  // Check if user is admin (username 'str8')
  const isAdmin = user && (user as any)?.username === 'str8';
  
  // Redirect non-admin users away from the Admin page
  useEffect(() => {
    if (!isAdmin) {
      setLocation('/');
    }
  }, [isAdmin, setLocation]);
  
  return (
    <main className="container mx-auto px-4 py-4">
      <div className="flex justify-between items-center mb-6">
        <div className="flex items-center gap-2">
          <Shield className="h-6 w-6 text-cyan" />
          <h2 className="text-2xl font-bold text-white">Admin Panel</h2>
        </div>
        
        <div className="flex items-center gap-2">
          <span className="text-sm text-cyan bg-space-800 px-3 py-1 rounded-full">
            v3.4 Admin
          </span>
        </div>
      </div>
      
      {/* Admin Navigation */}
      <div className="mb-6 bg-space-900 rounded-xl p-1 inline-flex flex-wrap">
        <button
          onClick={() => setActiveTab('dashboard')}
          className={`p-2 px-4 rounded-lg flex items-center ${
            activeTab === 'dashboard' 
              ? 'bg-purple-900 text-cyan' 
              : 'text-gray-300 hover:bg-space-800'
          }`}
        >
          <BarChart2 className="h-4 w-4 mr-2" />
          Dashboard
        </button>
        
        <button
          onClick={() => setActiveTab('users')}
          className={`p-2 px-4 rounded-lg flex items-center ${
            activeTab === 'users' 
              ? 'bg-purple-900 text-cyan' 
              : 'text-gray-300 hover:bg-space-800'
          }`}
        >
          <Users className="h-4 w-4 mr-2" />
          Users
        </button>
        
        <button
          onClick={() => setActiveTab('subscriptions')}
          className={`p-2 px-4 rounded-lg flex items-center ${
            activeTab === 'subscriptions' 
              ? 'bg-purple-900 text-cyan' 
              : 'text-gray-300 hover:bg-space-800'
          }`}
        >
          <CreditCard className="h-4 w-4 mr-2" />
          Subscriptions
        </button>
        
        <button
          onClick={() => setActiveTab('maintenance')}
          className={`p-2 px-4 rounded-lg flex items-center ${
            activeTab === 'maintenance' 
              ? 'bg-purple-900 text-cyan' 
              : 'text-gray-300 hover:bg-space-800'
          }`}
        >
          <Server className="h-4 w-4 mr-2" />
          Maintenance
        </button>
        
        <button
          onClick={() => setActiveTab('settings')}
          className={`p-2 px-4 rounded-lg flex items-center ${
            activeTab === 'settings' 
              ? 'bg-purple-900 text-cyan' 
              : 'text-gray-300 hover:bg-space-800'
          }`}
        >
          <Settings className="h-4 w-4 mr-2" />
          Settings
        </button>
      </div>
      
      {/* Tab Content */}
      <div className="p-6 rounded-xl glass-card bg-space-900">
        {activeTab === 'dashboard' && <AdminDashboard />}
        {activeTab === 'users' && <UserManagement />}
        {activeTab === 'subscriptions' && <SubscriptionManagement />}
        {activeTab === 'maintenance' && <SystemMaintenance />}
        {activeTab === 'settings' && <SimpleSystemSettings />}
      </div>
    </main>
  );
};

export default Admin;