import { FC, useState, useEffect } from 'react';
import GlassCard from '@/components/ui/GlassCard';
import { useWeather } from '@/hooks/useWeather';
import { useJobTimer } from '@/hooks/useJobTimer';

// List of construction trades
const TRADES = [
  { id: 'general', name: 'General Construction', icon: 'fa-hammer' },
  { id: 'carpentry', name: 'Carpentry', icon: 'fa-screwdriver' },
  { id: 'electrical', name: 'Electrical', icon: 'fa-bolt' },
  { id: 'plumbing', name: 'Plumbing', icon: 'fa-faucet' },
  { id: 'masonry', name: 'Masonry', icon: 'fa-cubes' },
  { id: 'roofing', name: 'Roofing', icon: 'fa-home' },
  { id: 'painting', name: 'Painting', icon: 'fa-paint-roller' },
  { id: 'excavation', name: 'Excavation', icon: 'fa-truck-monster' },
  { id: 'hvac', name: 'HVAC', icon: 'fa-temperature-high' },
  { id: 'flooring', name: 'Flooring', icon: 'fa-border-all' },
  { id: 'landscaping', name: 'Landscaping', icon: 'fa-leaf' },
];

interface ImpactRisk {
  category: string;
  risk: 'low' | 'medium' | 'high' | 'critical';
  color: string;
  icon: string;
  impact: string;
  recommendation: string;
}

interface MaterialImpact {
  material: string;
  impact: string;
  mitigationStrategy: string;
  icon: string;
}

interface Notification {
  type: 'alert' | 'warning' | 'info';
  message: string;
  time: string;
}

const WeatherImpactor: FC = () => {
  const { 
    currentWeather, 
    forecast, 
    location,
    detailedImpact,
  } = useWeather();
  
  const { currentJob } = useJobTimer();
  
  const [activeTab, setActiveTab] = useState<'impact' | 'material' | 'forecast'>('impact');
  const [selectedTrade, setSelectedTrade] = useState(TRADES[0].id);
  const [showTradeSelector, setShowTradeSelector] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [notifications, setNotifications] = useState<Notification[]>([
    { type: 'alert', message: 'Critical: High winds expected tomorrow - secure all materials', time: '10:15 AM' },
    { type: 'warning', message: 'Rain may delay concrete curing at Mount site', time: 'Yesterday' },
    { type: 'info', message: 'Weather clearing on Friday - optimal for exterior painting', time: 'Yesterday' },
  ]);
  
  // Calculate impact risks based on current weather and forecast
  const [impactRisks, setImpactRisks] = useState<ImpactRisk[]>([
    {
      category: 'Schedule',
      risk: 'medium',
      color: 'text-yellow-400',
      icon: 'fa-calendar-alt',
      impact: 'Expected 1-2 day delay due to rain',
      recommendation: 'Adjust timeline and notify clients of potential delays'
    },
    {
      category: 'Safety',
      risk: 'high',
      color: 'text-red-500',
      icon: 'fa-hard-hat',
      impact: 'Slippery conditions and reduced visibility',
      recommendation: 'Implement enhanced safety protocols and briefings'
    },
    {
      category: 'Equipment',
      risk: 'low',
      color: 'text-green-400',
      icon: 'fa-tools',
      impact: 'Minor impact on electrical equipment',
      recommendation: 'Ensure proper covering and storage of sensitive equipment'
    },
    {
      category: 'Quality',
      risk: 'medium',
      color: 'text-yellow-400',
      icon: 'fa-check-circle',
      impact: 'Moisture may affect material performance',
      recommendation: 'Increase quality checks and adjust material application'
    }
  ]);
  
  // Material impacts
  const [materialImpacts, setMaterialImpacts] = useState<MaterialImpact[]>([
    {
      material: 'Concrete',
      impact: 'Slower curing time, potential surface defects',
      mitigationStrategy: 'Use tarps and accelerants, reschedule pours if possible',
      icon: 'fa-cubes'
    },
    {
      material: 'Paint',
      impact: 'Longer drying time, potential runoff issues',
      mitigationStrategy: 'Use quick-dry formulations, avoid application 24h before rain',
      icon: 'fa-fill-drip'
    },
    {
      material: 'Lumber',
      impact: 'Increased moisture content, potential warping',
      mitigationStrategy: 'Store properly under cover, allow extra drying time',
      icon: 'fa-wood'
    },
    {
      material: 'Roofing',
      impact: 'Unsafe installation conditions, adhesive issues',
      mitigationStrategy: 'Postpone installation, use mechanical fasteners',
      icon: 'fa-home'
    }
  ]);
  
  // Calculate overall project risk
  const calculateOverallRisk = (): { level: string; color: string; percentage: number } => {
    const riskMap = { low: 1, medium: 2, high: 3, critical: 4 };
    const totalRisk = impactRisks.reduce((acc, risk) => acc + riskMap[risk.risk], 0);
    const maxPossibleRisk = impactRisks.length * 4; // maximum possible risk score
    const riskPercentage = (totalRisk / maxPossibleRisk) * 100;
    
    if (riskPercentage >= 75) return { level: 'Critical', color: 'text-red-500', percentage: riskPercentage };
    if (riskPercentage >= 50) return { level: 'High', color: 'text-orange-500', percentage: riskPercentage };
    if (riskPercentage >= 25) return { level: 'Medium', color: 'text-yellow-400', percentage: riskPercentage };
    return { level: 'Low', color: 'text-green-400', percentage: riskPercentage };
  };
  
  const overallRisk = calculateOverallRisk();
  
  // Risk level badge component
  const RiskBadge: FC<{ risk: 'low' | 'medium' | 'high' | 'critical' }> = ({ risk }) => {
    const colors = {
      low: 'bg-green-900/30 text-green-400',
      medium: 'bg-yellow-900/30 text-yellow-400',
      high: 'bg-orange-900/30 text-orange-400',
      critical: 'bg-red-900/30 text-red-400'
    };
    
    return (
      <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${colors[risk]}`}>
        {risk.charAt(0).toUpperCase() + risk.slice(1)}
      </span>
    );
  };
  
  const getWeatherTrendIcon = () => {
    // Compare today's temperature with tomorrow's to determine trend
    if (forecast.length >= 2) {
      const todayTemp = forecast[0].temp;
      const tomorrowTemp = forecast[1].temp;
      
      if (tomorrowTemp > todayTemp + 2) return 'fa-temperature-up text-red-400';
      if (tomorrowTemp < todayTemp - 2) return 'fa-temperature-down text-blue-400';
    }
    return 'fa-temperature-half text-gray-400';
  };
  
  return (
    <GlassCard 
      className="rounded-xl mb-6 overflow-hidden p-0"
      variant="electric"
      glow={true}
    >
      {/* Header */}
      <div className="flex justify-between items-center px-5 py-3 border-b border-electric/20">
        <div className="flex items-center">
          <i className="fas fa-cloud-sun-rain mr-2 text-electric"></i>
          <h3 className="text-lg font-space text-white">Weather Impact Analyzer</h3>
          <div className="ml-2 px-2 py-1 bg-space-900/40 rounded-md">
            <span className="text-xs text-gray-300">{location}</span>
          </div>
        </div>
        <div className="flex items-center space-x-2">
          <span className={`text-lg ${getWeatherTrendIcon().split(' ')[1]}`}>
            <i className={`fas ${getWeatherTrendIcon().split(' ')[0]}`}></i>
          </span>
          <div className="text-2xl font-medium text-white">
            {currentWeather.temp}°C
          </div>
        </div>
      </div>
      
      {/* Tabs */}
      <div className="flex border-b border-space-700/30 px-5 bg-space-900/30">
        <button
          className={`px-4 py-2.5 text-sm font-medium relative ${activeTab === 'impact' ? 'text-electric' : 'text-gray-400 hover:text-gray-300'}`}
          onClick={() => setActiveTab('impact')}
        >
          <i className="fas fa-exclamation-triangle mr-1.5"></i>
          Impact Analysis
          {activeTab === 'impact' && <span className="absolute bottom-0 left-0 right-0 h-0.5 bg-electric"></span>}
        </button>
        <button
          className={`px-4 py-2.5 text-sm font-medium relative ${activeTab === 'material' ? 'text-electric' : 'text-gray-400 hover:text-gray-300'}`}
          onClick={() => setActiveTab('material')}
        >
          <i className="fas fa-cubes mr-1.5"></i>
          Material Advisory
          {activeTab === 'material' && <span className="absolute bottom-0 left-0 right-0 h-0.5 bg-electric"></span>}
        </button>
        <button
          className={`px-4 py-2.5 text-sm font-medium relative ${activeTab === 'forecast' ? 'text-electric' : 'text-gray-400 hover:text-gray-300'}`}
          onClick={() => setActiveTab('forecast')}
        >
          <i className="fas fa-chart-line mr-1.5"></i>
          Forecast Impact
          {activeTab === 'forecast' && <span className="absolute bottom-0 left-0 right-0 h-0.5 bg-electric"></span>}
        </button>
      </div>
      
      {/* Main content area */}
      <div className="p-5">
        {/* Impact Analysis Tab */}
        {activeTab === 'impact' && (
          <div>
            {/* Overall risk meter */}
            <div className="mb-5">
              <div className="flex justify-between items-center mb-2">
                <h4 className="text-sm font-medium text-white">Overall Project Risk</h4>
                <span className={`text-sm font-medium ${overallRisk.color}`}>{overallRisk.level} Risk</span>
              </div>
              <div className="w-full h-2 bg-space-800 rounded-full overflow-hidden">
                <div 
                  className={`h-full transition-all duration-1000 ease-out ${overallRisk.level === 'Low' ? 'bg-gradient-to-r from-green-500/70 to-green-400' : 
                  overallRisk.level === 'Medium' ? 'bg-gradient-to-r from-yellow-500/70 to-yellow-400' : 
                  overallRisk.level === 'High' ? 'bg-gradient-to-r from-orange-500/70 to-orange-400' : 
                  'bg-gradient-to-r from-red-600/70 to-red-500'}`}
                  style={{ width: `${overallRisk.percentage}%` }}
                ></div>
              </div>
            </div>
            
            {/* Impact categories */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              {impactRisks.map((impact, index) => (
                <div key={index} className="bg-space-900/40 rounded-lg p-3">
                  <div className="flex justify-between items-start mb-2">
                    <div className="flex items-center">
                      <div className={`w-8 h-8 rounded-full bg-space-800 flex items-center justify-center ${impact.color} mr-2`}>
                        <i className={`fas ${impact.icon}`}></i>
                      </div>
                      <div>
                        <h5 className="text-sm font-medium text-white">{impact.category}</h5>
                        <div className="text-xs text-gray-400">Risk Level: <RiskBadge risk={impact.risk} /></div>
                      </div>
                    </div>
                  </div>
                  <p className="text-sm text-white mb-1">{impact.impact}</p>
                  <p className="text-xs text-cyan-400"><i className="fas fa-lightbulb mr-1"></i> {impact.recommendation}</p>
                </div>
              ))}
            </div>
            
            {/* Trade Selection Box */}
            <div className="mt-5 mb-5 bg-space-800/80 rounded-lg p-4 border border-electric/30">
              <div className="flex justify-between items-center mb-3">
                <h4 className="text-sm font-medium text-white">
                  <i className="fas fa-hard-hat mr-1.5 text-electric"></i>
                  Trade-Specific Weather Impact
                </h4>
                <div className="relative">
                  <button
                    onClick={() => setShowTradeSelector(!showTradeSelector)}
                    className="bg-space-900/70 hover:bg-space-900 text-white px-3 py-1.5 rounded-md text-xs flex items-center transition-colors"
                  >
                    <i className={`fas ${TRADES.find(t => t.id === selectedTrade)?.icon || 'fa-hammer'} mr-1.5`}></i>
                    {TRADES.find(t => t.id === selectedTrade)?.name || 'Select Trade'}
                    <i className={`fas fa-chevron-${showTradeSelector ? 'up' : 'down'} ml-2 text-gray-400`}></i>
                  </button>
                  
                  {showTradeSelector && (
                    <div className="absolute right-0 mt-1 w-64 bg-space-900 rounded-lg shadow-lg border border-electric/20 z-10 max-h-72 overflow-y-auto">
                      {TRADES.map(trade => (
                        <button
                          key={trade.id}
                          className={`w-full text-left px-3 py-2.5 text-sm flex items-center hover:bg-space-800 transition-colors ${
                            selectedTrade === trade.id ? 'bg-electric/10 text-electric' : 'text-white'
                          }`}
                          onClick={() => {
                            setSelectedTrade(trade.id);
                            setShowTradeSelector(false);
                            setIsAnalyzing(true);
                            // Simulate analysis delay
                            setTimeout(() => setIsAnalyzing(false), 800);
                          }}
                        >
                          <i className={`fas ${trade.icon} w-5 mr-2`}></i>
                          {trade.name}
                          {selectedTrade === trade.id && <i className="fas fa-check ml-auto"></i>}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              </div>
              
              {isAnalyzing ? (
                <div className="flex items-center justify-center py-6">
                  <div className="animate-spin h-5 w-5 border-2 border-electric border-t-transparent rounded-full mr-2"></div>
                  <span className="text-sm text-gray-300">Analyzing impact for {TRADES.find(t => t.id === selectedTrade)?.name}...</span>
                </div>
              ) : (
                <div className="space-y-3">
                  {/* Trade-specific impact */}
                  {selectedTrade === 'painting' && (
                    <div>
                      <div className="flex items-start mb-2">
                        <div className="h-6 w-6 rounded-full bg-space-900 flex items-center justify-center text-red-400 mr-2">
                          <i className="fas fa-exclamation-triangle text-xs"></i>
                        </div>
                        <p className="text-sm text-white">Painting operations severely affected by current weather conditions.</p>
                      </div>
                      <ul className="pl-8 text-sm space-y-1.5">
                        <li className="text-gray-300"><span className="text-red-400">•</span> Exterior painting should be postponed (humidity above 70%)</li>
                        <li className="text-gray-300"><span className="text-yellow-400">•</span> Interior painting possible with proper ventilation</li>
                        <li className="text-gray-300"><span className="text-green-400">•</span> Recommend scheduling exterior work for Friday (optimal conditions)</li>
                      </ul>
                    </div>
                  )}
                  
                  {selectedTrade === 'electrical' && (
                    <div>
                      <div className="flex items-start mb-2">
                        <div className="h-6 w-6 rounded-full bg-space-900 flex items-center justify-center text-yellow-400 mr-2">
                          <i className="fas fa-bolt text-xs"></i>
                        </div>
                        <p className="text-sm text-white">Electrical work partially affected by current weather conditions.</p>
                      </div>
                      <ul className="pl-8 text-sm space-y-1.5">
                        <li className="text-gray-300"><span className="text-yellow-400">•</span> Outdoor electrical installations should use weather-proof equipment</li>
                        <li className="text-gray-300"><span className="text-green-400">•</span> Indoor electrical work can proceed as normal</li>
                        <li className="text-gray-300"><span className="text-yellow-400">•</span> Extra care needed with temporary power connections</li>
                      </ul>
                    </div>
                  )}
                  
                  {selectedTrade === 'roofing' && (
                    <div>
                      <div className="flex items-start mb-2">
                        <div className="h-6 w-6 rounded-full bg-space-900 flex items-center justify-center text-red-400 mr-2">
                          <i className="fas fa-exclamation-circle text-xs"></i>
                        </div>
                        <p className="text-sm text-white">Roofing operations severely affected by current weather conditions.</p>
                      </div>
                      <ul className="pl-8 text-sm space-y-1.5">
                        <li className="text-gray-300"><span className="text-red-400">•</span> All roofing installation should be postponed due to safety concerns</li>
                        <li className="text-gray-300"><span className="text-red-400">•</span> High risk of water infiltration and material damage</li>
                        <li className="text-gray-300"><span className="text-yellow-400">•</span> Ensure temporary coverings are secure with additional fasteners</li>
                      </ul>
                    </div>
                  )}
                  
                  {(selectedTrade !== 'painting' && selectedTrade !== 'electrical' && selectedTrade !== 'roofing') && (
                    <div>
                      <div className="flex items-start mb-2">
                        <div className="h-6 w-6 rounded-full bg-space-900 flex items-center justify-center text-yellow-400 mr-2">
                          <i className={`fas ${TRADES.find(t => t.id === selectedTrade)?.icon || 'fa-hard-hat'} text-xs`}></i>
                        </div>
                        <p className="text-sm text-white">{TRADES.find(t => t.id === selectedTrade)?.name || 'Selected trade'} operations moderately affected by current weather.</p>
                      </div>
                      <ul className="pl-8 text-sm space-y-1.5">
                        <li className="text-gray-300"><span className="text-yellow-400">•</span> Consider adjusting outdoor work schedule due to rain</li>
                        <li className="text-gray-300"><span className="text-green-400">•</span> Indoor operations can continue as scheduled</li>
                        <li className="text-gray-300"><span className="text-yellow-400">•</span> Monitor weather changes throughout the day for safer operations</li>
                      </ul>
                    </div>
                  )}
                  
                  <div className="bg-electric/10 rounded-lg p-2.5 mt-3">
                    <h5 className="text-xs font-medium text-electric mb-1.5">Productivity Impact Analysis</h5>
                    <div className="flex justify-between items-center mb-1.5">
                      <span className="text-xs text-white">Estimated productivity impact:</span>
                      <span className="text-xs font-medium text-yellow-400">{selectedTrade === 'roofing' || selectedTrade === 'painting' ? 'Severe (-40-60%)' : selectedTrade === 'electrical' ? 'Moderate (-15-25%)' : 'Moderate (-20-30%)'}</span>
                    </div>
                    <div className="w-full h-1.5 bg-space-900 rounded-full overflow-hidden">
                      <div className={`h-full ${
                        selectedTrade === 'roofing' || selectedTrade === 'painting' ? 'bg-red-500 w-[55%]' : 
                        selectedTrade === 'electrical' ? 'bg-yellow-500 w-[20%]' : 'bg-yellow-500 w-[25%]'
                      }`}></div>
                    </div>
                  </div>
                </div>
              )}
              
              <div className="mt-3 flex justify-between items-center">
                <span className="text-xs text-gray-400"><i className="fas fa-clock mr-1"></i> Updated just now</span>
                <button className="text-xs bg-electric/20 hover:bg-electric/30 text-electric hover:text-white px-2.5 py-1 rounded transition-colors">
                  <i className="fas fa-file-download mr-1"></i> Export Report
                </button>
              </div>
            </div>
            
            {/* Current job impact */}
            <div className="mt-5 bg-space-800/60 rounded-lg p-4 border-l-4 border-electric">
              <h4 className="text-sm font-medium text-white mb-2">Current Job Impact: {currentJob.name}</h4>
              <p className="text-sm text-gray-300">
                {detailedImpact.summary}. Consider adjusting the schedule to account for weather conditions.
              </p>
              <div className="mt-3 flex justify-between">
                <span className="text-xs text-gray-400"><i className="fas fa-clock mr-1"></i> Updated 10 mins ago</span>
                <button className="text-xs text-electric hover:text-cyan-400 transition-colors">
                  View detailed report <i className="fas fa-chevron-right ml-1"></i>
                </button>
              </div>
            </div>
          </div>
        )}
        
        {/* Material Advisory Tab */}
        {activeTab === 'material' && (
          <div>
            <div className="grid grid-cols-1 gap-3">
              {materialImpacts.map((material, index) => (
                <div key={index} className="bg-space-900/40 rounded-lg p-3 flex items-start">
                  <div className="w-10 h-10 rounded-full bg-space-800 flex items-center justify-center text-electric mr-3 mt-1">
                    <i className={`fas ${material.icon}`}></i>
                  </div>
                  <div className="flex-1">
                    <h5 className="text-sm font-medium text-white">{material.material}</h5>
                    <p className="text-xs text-gray-300 mb-1">{material.impact}</p>
                    <div className="bg-electric/10 rounded-lg p-2 border-l-2 border-electric/50">
                      <p className="text-xs text-electric"><strong>Mitigation:</strong> {material.mitigationStrategy}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
            
            <div className="mt-4 p-3 bg-space-900/40 rounded-lg">
              <h4 className="text-sm font-medium text-white mb-2">Material Delivery Advisory</h4>
              <p className="text-xs text-gray-300">
                <i className="fas fa-truck mr-1 text-yellow-400"></i> Potential delivery delays for cement and aggregates due to road conditions. Consider scheduling deliveries 1-2 days earlier than needed.
              </p>
            </div>
          </div>
        )}
        
        {/* Forecast Impact Tab */}
        {activeTab === 'forecast' && (
          <div>
            <div className="grid grid-cols-5 gap-2 mb-4">
              {forecast.map((day, index) => (
                <div 
                  key={index} 
                  className={`bg-space-900/40 rounded-lg p-2 text-center ${index === 0 ? 'border border-electric/40' : ''}`}
                >
                  <div className="text-xs text-gray-400">{day.day}</div>
                  <div className="my-1"><i className={`fas ${day.icon} ${day.icon.includes('sun') ? 'text-yellow-400' : day.icon.includes('rain') ? 'text-blue-400' : 'text-gray-400'}`}></i></div>
                  <div className="text-sm font-medium text-white">{day.temp}°C</div>
                  <div className="text-xs text-gray-500 mt-1">{day.conditions}</div>
                  <div className={`text-xs mt-1 ${day.conditions.toLowerCase().includes('rain') ? 'text-red-400' : 'text-green-400'}`}>
                    {day.conditions.toLowerCase().includes('rain') ? 'High Impact' : 'Low Impact'}
                  </div>
                </div>
              ))}
            </div>
            
            <div className="bg-space-900/40 rounded-lg p-3 mb-3">
              <h4 className="text-sm font-medium text-white mb-2">5-Day Construction Outlook</h4>
              <div className="text-xs text-gray-300 space-y-1">
                <div><strong>Today:</strong> Delay exterior work until afternoon when rain subsides</div>
                <div><strong>Tomorrow:</strong> Optimal conditions for all work types</div>
                <div><strong>Friday:</strong> Schedule exterior painting and concrete pours</div>
                <div><strong>Saturday:</strong> Normal operations with minor wind concerns</div>
                <div><strong>Sunday:</strong> Plan for indoor work only - severe weather expected</div>
              </div>
            </div>
            
            {/* Notifications */}
            <div className="bg-space-900/40 rounded-lg p-3">
              <div className="flex justify-between items-center mb-2">
                <h4 className="text-sm font-medium text-white">Weather Alerts</h4>
                <span className="text-xs text-gray-400">{notifications.length} new</span>
              </div>
              <div className="space-y-2 max-h-32 overflow-y-auto">
                {notifications.map((notification, index) => (
                  <div 
                    key={index} 
                    className={`text-xs p-2 rounded-lg flex justify-between items-start ${notification.type === 'alert' ? 'bg-red-900/20 border-l-2 border-red-500' : 
                      notification.type === 'warning' ? 'bg-yellow-900/20 border-l-2 border-yellow-500' : 
                      'bg-blue-900/20 border-l-2 border-blue-500'}`}
                  >
                    <div>
                      <i className={`fas ${notification.type === 'alert' ? 'fa-exclamation-circle text-red-500' : 
                        notification.type === 'warning' ? 'fa-exclamation-triangle text-yellow-500' : 
                        'fa-info-circle text-blue-500'} mr-1.5`}></i>
                      {notification.message}
                    </div>
                    <div className="text-gray-400 ml-2">{notification.time}</div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
      
      {/* Footer */}
      <div className="bg-space-900/80 px-5 py-3 flex justify-between items-center border-t border-electric/10">
        <div className="text-xs text-gray-400">
          <i className="fas fa-sync fa-spin text-electric mr-1.5"></i>
          Auto-refreshing every 30 minutes
        </div>
        <button className="bg-electric/20 hover:bg-electric/30 text-electric hover:text-white px-3 py-1 rounded-md text-xs transition-all duration-200">
          <i className="fas fa-bolt mr-1.5"></i>
          Generate Mitigation Plan
        </button>
      </div>
    </GlassCard>
  );
};

export default WeatherImpactor;
