import { FC, useState } from 'react';
import { z } from 'zod';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Link } from 'wouter';
import { useAuth } from '@/hooks/useAuth';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Separator } from '@/components/ui/separator';
import { useToast } from '@/hooks/use-toast';
import { APP_NAME } from '@/lib/constants';
import { LucideLoader2 } from 'lucide-react';
import str8BuildLogo from '@/assets/str8-build-logo.png';
import PWAInstallPrompt from '@/components/PWAInstallPrompt';
import InstallPrompt from '../components/ui/InstallPrompt';
import { motion } from 'framer-motion';

// Define login form schema
const loginSchema = z.object({
  username: z.string().min(3, { message: 'Username must be at least 3 characters' }),
  password: z.string().min(6, { message: 'Password must be at least 6 characters' }),
});

type LoginFormValues = z.infer<typeof loginSchema>;

const Login: FC = () => {
  const { login } = useAuth();
  const [isLoading, setIsLoading] = useState(false);
  const { toast } = useToast();

  // Initialize form
  const form = useForm<LoginFormValues>({
    resolver: zodResolver(loginSchema),
    defaultValues: {
      username: '',
      password: '',
    },
  });

  // Clean login handler - uses only API authentication
  const onSubmit = async (data: LoginFormValues) => {
    setIsLoading(true);
    
    try {
      const trimmedUsername = data.username.trim();
      console.log("Login attempt with username:", trimmedUsername);
      
      // Use the standard API login
      await login(trimmedUsername, data.password);
      
      // Success message for API login
      toast({
        title: "Login successful",
        description: "Welcome to STR8 BUILD!",
        duration: 2000,
      });
      
      // Redirect to dashboard after a small delay
      setTimeout(() => {
        window.location.href = '/';
      }, 300);
      
    } catch (error: any) {
      console.error("Login process failed:", error);
      
      // Reset loading state
      setIsLoading(false);
      
      // Show appropriate error message
      let errorMessage = "Invalid credentials";
      
      if (error?.message) {
        errorMessage = error.message;
      } else if (error?.toString) {
        errorMessage = error.toString();
      }
      
      toast({
        variant: "destructive",
        title: "Login failed",
        description: errorMessage,
        duration: 3000,
      });
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-900 via-gray-900 to-gray-800 flex flex-col justify-center py-12 px-6 lg:px-8">
      <InstallPrompt forceShow={true} />
      <div className="sm:mx-auto sm:w-full sm:max-w-md">
        {/* PWA Install Prompt */}
        <PWAInstallPrompt />
        
        {/* Enhanced Logo Section */}
        <motion.div 
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          className="mb-12 text-center"
        >
          <div className="relative inline-block">
            <img 
              src={str8BuildLogo} 
              alt="STR8 BUILD Logo" 
              className="w-64 h-auto mx-auto drop-shadow-[0_0_25px_rgba(34,211,238,0.6)] hover:drop-shadow-[0_0_35px_rgba(34,211,238,0.8)] transition-all duration-500 transform hover:scale-105"
            />
            <div className="absolute inset-0 bg-gradient-to-r from-cyan-400/20 to-blue-500/20 rounded-full blur-xl -z-10"></div>
          </div>

          <motion.p 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.5, duration: 0.6 }}
            className="mt-2 text-lg text-cyan-300 font-medium"
          >
            Professional Construction Management
          </motion.p>
        </motion.div>

        {/* Enhanced Login Card */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2, duration: 0.6 }}
        >
          <Card className="w-full max-w-md bg-gray-800/60 backdrop-blur-lg border-gray-700/50 shadow-2xl overflow-hidden ring-1 ring-cyan-500/20">
            <CardHeader className="border-b border-gray-700/50 bg-gradient-to-r from-gray-800/80 to-gray-700/80">
              <CardTitle className="text-2xl font-bold text-cyan-400 text-center">Welcome Back</CardTitle>
              <CardDescription className="text-gray-300 text-center">
                Sign in to your {APP_NAME} account
              </CardDescription>
            </CardHeader>
            <CardContent className="p-8">
              <Form {...form}>
                <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
                  <FormField
                    control={form.control}
                    name="username"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-gray-300 font-medium">Username</FormLabel>
                        <FormControl>
                          <Input 
                            {...field} 
                            className="bg-gray-700/80 border-gray-600 text-white focus:ring-2 focus:ring-cyan-500 focus:border-transparent h-12 text-lg"
                            placeholder="Enter your username"
                          />
                        </FormControl>
                        <FormMessage className="text-rose-400" />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="password"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-gray-300 font-medium">Password</FormLabel>
                        <FormControl>
                          <Input 
                            type="password" 
                            {...field} 
                            className="bg-gray-700/80 border-gray-600 text-white focus:ring-2 focus:ring-cyan-500 focus:border-transparent h-12 text-lg"
                            placeholder="Enter your password"
                          />
                        </FormControl>
                        <FormMessage className="text-rose-400" />
                      </FormItem>
                    )}
                  />
                  <Button 
                    type="submit" 
                    className="w-full h-12 mt-8 bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-500 hover:to-blue-500 text-white font-semibold text-lg transition-all duration-300 hover:shadow-lg hover:shadow-cyan-500/30 transform hover:scale-[1.02]"
                    disabled={isLoading}
                  >
                    {isLoading ? (
                      <LucideLoader2 className="mr-2 h-5 w-5 animate-spin" />
                    ) : null}
                    Sign In
                  </Button>
                </form>
              </Form>
              
              <div className="mt-6 text-center">
                <Separator className="my-6 bg-gray-600" />
                
                <p className="text-sm text-gray-400">
                  Don't have an account?{' '}
                  <Link href="/register" className="text-cyan-400 hover:text-cyan-300 font-medium transition-colors">
                    Create Account
                  </Link>
                </p>
              </div>
            </CardContent>
            <CardFooter className="flex justify-center text-xs text-gray-500 bg-gray-800/40 py-4">
              &copy; {new Date().getFullYear()} STR8 BUILD Ltd. All rights reserved.
            </CardFooter>
          </Card>
        </motion.div>
      </div>
    </div>
  );
};

export default Login;
