import { FC, useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { usePWAInstall } from '@/hooks/usePWAInstall'; 
import { X } from 'lucide-react';
import str8BuildLogo from '@/assets/str8-build-logo.png';

interface PWAInstallPromptProps {
  className?: string;
}

const PWAInstallPrompt: FC<PWAInstallPromptProps> = ({ className = '' }) => {
  const [showBanner, setShowBanner] = useState(false);
  const { canInstall: installable, installApp: promptInstall } = usePWAInstall();

  // Show the banner if the app can be installed after a short delay
  useEffect(() => {
    if (installable) {
      // Check if the user has dismissed the prompt before
      const hasPromptBeenDismissed = localStorage.getItem('pwaPromptDismissed') === 'true';
      
      if (!hasPromptBeenDismissed) {
        // Show the prompt sooner on login/register pages
        const isAuthPage = window.location.pathname.includes('/login') || 
                           window.location.pathname.includes('/register');
        
        const timer = setTimeout(() => {
          setShowBanner(true);
        }, isAuthPage ? 1000 : 3000); // Show after 1 second on auth pages, 3 seconds elsewhere
        
        return () => clearTimeout(timer);
      }
    }
  }, [installable]);

  // Handle install button click
  const handleInstallClick = () => {
    promptInstall();
    setShowBanner(false);
  };

  // Close the banner
  const handleClose = () => {
    setShowBanner(false);
    
    // Store in localStorage so we don't show the prompt again in this session
    localStorage.setItem('pwaPromptDismissed', 'true');
  };
  
  if (!installable || !showBanner) return null;
  
  return (
    <AnimatePresence>
      {showBanner && (
        <motion.div
          className={`fixed bottom-16 left-0 right-0 z-50 mx-auto px-4 ${className}`}
          initial={{ y: 100, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: 100, opacity: 0 }}
          transition={{ type: "spring", stiffness: 300, damping: 30 }}
        >
          <div className="max-w-md mx-auto bg-gradient-to-br from-space-800 to-space-900 rounded-xl shadow-2xl overflow-hidden border border-blue-500/30">
            <div className="p-4 relative">
              <button 
                onClick={handleClose}
                className="absolute top-2 right-2 p-1 text-gray-400 hover:text-white rounded-full"
              >
                <X size={20} />
              </button>
              
              <div className="flex items-center">
                <img 
                  src={str8BuildLogo} 
                  alt="STR8 BUILD" 
                  className="w-14 h-auto mr-4 drop-shadow-[0_0_8px_rgba(59,130,246,0.5)]" 
                />
                <div>
                  <h3 className="text-lg font-bold text-white">Install STR8 BUILD</h3>
                  <p className="text-sm text-blue-200">Add to your home screen for quick access</p>
                </div>
              </div>
              
              <div className="mt-3 flex justify-end">
                <button 
                  onClick={handleClose}
                  className="mr-2 px-3 py-1.5 text-sm text-blue-300 hover:text-blue-100"
                >
                  Not now
                </button>
                <button 
                  onClick={handleInstallClick}
                  className="px-4 py-1.5 text-sm font-medium bg-blue-600 text-white rounded-md hover:bg-blue-700"
                >
                  Install
                </button>
              </div>
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default PWAInstallPrompt;