import { FC } from 'react';
import GlassCard from '@/components/ui/GlassCard';

const PendingInvoices: FC = () => {
  const invoices = [
    { id: 1, number: 'INV-2025-042', client: 'Bay Builders Ltd', dueDate: 'Due in 5 days', amount: 1450.00, overdue: false },
    { id: 2, number: 'INV-2025-039', client: 'Tauranga Home Concepts', dueDate: 'Overdue', amount: 2440.50, overdue: true },
  ];
  
  const totalAmount = invoices.reduce((sum, invoice) => sum + invoice.amount, 0);
  
  return (
    <GlassCard className="p-4">
      <div className="flex justify-between items-start mb-3">
        <h3 className="text-md font-space text-white">Pending Invoices</h3>
        <span className="text-cyan"><i className="fas fa-file-invoice-dollar"></i></span>
      </div>
      
      <div className="text-2xl font-space font-bold text-cyan mb-2">${totalAmount.toFixed(2)}</div>
      
      <div className="space-y-1">
        {invoices.map(invoice => (
          <div 
            key={invoice.id} 
            className={`flex justify-between items-center py-2 border-b border-gray-700 relative rounded ${
              !invoice.overdue ? 'active-job-card px-2 -mx-2' : ''
            }`}
          >
            <div className="text-sm">
              <div className="flex items-center">
                {!invoice.overdue && (
                  <span className="h-2 w-2 rounded-full bg-green-400 mr-1.5 animate-pulse"></span>
                )}
                <span className="text-white">{invoice.number}</span>
              </div>
              <div className="text-xs text-gray-400">{invoice.client} | {invoice.dueDate}</div>
            </div>
            <div className={`text-sm font-medium ${invoice.overdue ? 'text-red-400' : 'text-cyan'}`}>
              ${invoice.amount.toFixed(2)}
            </div>
          </div>
        ))}
      </div>
      
      <div className="mt-3">
        <button className="text-sm text-cyan hover:text-white w-full py-2 border border-cyan/30 rounded-md btn-glow btn-glow-cyan">
          Create New Invoice
        </button>
      </div>
    </GlassCard>
  );
};

export default PendingInvoices;
