import { FC } from 'react';
import GlassCard from '@/components/ui/GlassCard';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog';

interface WidgetOption {
  id: string;
  title: string;
  description: string;
  icon: string;
  disabled?: boolean;
}

interface AddWidgetDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  availableWidgets: WidgetOption[];
  onAddWidget: (widgetId: string) => void;
}

const AddWidgetDialog: FC<AddWidgetDialogProps> = ({
  open,
  onOpenChange,
  availableWidgets,
  onAddWidget
}) => {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-space-900/95 border-space-700 text-white max-w-4xl">
        <DialogHeader>
          <DialogTitle className="text-xl font-space text-white">Add Widgets to Dashboard</DialogTitle>
          <DialogDescription className="text-gray-400">
            Select widgets to add to your dashboard. You can customize their position later.
          </DialogDescription>
        </DialogHeader>
        
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4 mt-4">
          {availableWidgets.map(widget => (
            <GlassCard 
              key={widget.id}
              className={`p-4 transition-all hover:border-cyan cursor-pointer ${widget.disabled ? 'opacity-50 pointer-events-none' : ''}`}
              onClick={() => {
                if (!widget.disabled) {
                  onAddWidget(widget.id);
                }
              }}
            >
              <div className="flex items-start gap-3">
                <div className="text-2xl text-cyan">
                  <i className={`fas ${widget.icon}`}></i>
                </div>
                <div>
                  <h3 className="text-white font-medium">{widget.title}</h3>
                  <p className="text-gray-400 text-sm mt-1">{widget.description}</p>
                  {widget.disabled && (
                    <div className="text-yellow-400 text-xs mt-2">
                      <i className="fas fa-info-circle mr-1"></i> Already on dashboard
                    </div>
                  )}
                </div>
              </div>
            </GlassCard>
          ))}
        </div>
        
        <div className="mt-6 flex justify-end">
          <button
            className="bg-space-800 text-white px-4 py-2 rounded hover:bg-space-700 mr-2"
            onClick={() => onOpenChange(false)}
          >
            Cancel
          </button>
          <button
            className="bg-purple-900 text-cyan px-4 py-2 rounded hover:bg-purple-800 btn-glow btn-glow-cyan"
            onClick={() => onOpenChange(false)}
          >
            Done
          </button>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default AddWidgetDialog;