import { FC } from 'react';
import { useTimeEntries } from '@/hooks/useTimeEntries';
import { TimeEntry } from '@shared/schema';

const TimeEntriesList: FC = () => {
  const { 
    timeEntries = [], 
    isLoading, 
    formatDuration, 
    formatDate,
    calculateCost
  } = useTimeEntries();
  
  // Explicitly type the time entries array
  const typedTimeEntries = timeEntries as TimeEntry[];

  if (isLoading) {
    return (
      <div className="space-y-2">
        <div className="flex justify-center p-10">
          <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-teal"></div>
        </div>
      </div>
    );
  }

  if (typedTimeEntries.length === 0) {
    return (
      <div className="space-y-2">
        <div className="p-6 text-center bg-space-800/50 rounded-lg">
          <p className="text-gray-400">No time entries found.</p>
          <p className="text-xs text-gray-500 mt-1">Add a new time entry to get started.</p>
        </div>
      </div>
    );
  }

  // Use typed time entries array
  const displayEntries = typedTimeEntries;

  return (
    <div className="space-y-2">
      {displayEntries.map((entry: TimeEntry) => (
        <div 
          key={entry.id} 
          className="flex justify-between items-center p-3 bg-space-800/50 rounded-lg hover:bg-space-800/80 transition-colors"
        >
          <div className="flex-1">
            <div className="text-sm font-medium text-white">
              {entry.projectId ? `Project #${entry.projectId}` : 'No Project'}
            </div>
            <div className="text-xs text-gray-400">
              {formatDate(entry.startTime.toString())}
              {entry.notes && ` | ${entry.notes.substring(0, 30)}${entry.notes.length > 30 ? '...' : ''}`}
            </div>
          </div>
          <div className="flex flex-col items-end">
            <div className="text-sm font-medium text-teal">
              ${(entry.duration && entry.hourlyRate) 
                ? calculateCost(entry.duration, entry.hourlyRate) 
                : '0.00'}
            </div>
            <div className="text-xs text-gray-400">
              {entry.duration ? formatDuration(entry.duration) : '0:00'} @ ${entry.hourlyRate 
                ? parseFloat(entry.hourlyRate.toString()).toFixed(2)
                : '0.00'}/hr
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

export default TimeEntriesList;