import { FC, useState, useEffect } from 'react';
import PageTitle from '@/components/ui/PageTitle';
import GlassCard from '@/components/ui/GlassCard';
import { useInvoices } from '@/hooks/useInvoices';
import { useClients } from '@/hooks/useClients';
import { useTimeEntries } from '@/hooks/useTimeEntries';
import { useProjects } from '@/hooks/useProjects';
import { Invoice, Client, TimeEntry, Project } from '@shared/schema';
import { toast } from '@/hooks/use-toast';

const CombinedPage: FC = () => {
  // Tab state for switching between invoices and timesheets
  const [activeSection, setActiveSection] = useState<'invoices' | 'timesheet'>('invoices');
  const [isDropdownOpen, setIsDropdownOpen] = useState<boolean>(false);
  
  // Effect to handle clicking outside of the dropdown to close it
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const dropdown = document.querySelector('.dropdown');
      if (dropdown && !dropdown.contains(event.target as Node) && isDropdownOpen) {
        setIsDropdownOpen(false);
      }
    };
    
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isDropdownOpen]);
  
  // === INVOICES SECTION ===
  const { 
    invoices = [], 
    isLoading: invoicesLoading, 
    createInvoice,
    isModalOpen,
    closeModal,
    selectedInvoice,
    openCreateModal,
    openDetailModal
  } = useInvoices();
  
  // Helper function to format currency
  const formatCurrency = (amount: number): string => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
    }).format(amount);
  };
  
  // Helper function to get status text
  const getStatusText = (status: string): string => {
    switch (status) {
      case 'draft':
        return 'Draft';
      case 'sent':
        return 'Sent';
      case 'paid':
        return 'Paid';
      case 'overdue':
        return 'Overdue';
      default:
        return status;
    }
  };
  
  const { clients = [] } = useClients() as { clients: Client[] };
  const { projects = [] } = useProjects() as { projects: Project[] };
  const [invoiceTab, setInvoiceTab] = useState<string>('all');
  const [invoiceSearchTerm, setInvoiceSearchTerm] = useState<string>('');
  
  // Get client name from ID
  const getClientName = (clientId: number | null): string => {
    if (!clientId) return 'No Client';
    const client = clients.find((c: Client) => c.id === clientId);
    return client ? client.name : `Client #${clientId}`;
  };

  // Filter invoices based on active tab and search term
  const filteredInvoices = (invoices as Invoice[]).filter((invoice: Invoice) => {
    const matchesTab = 
      invoiceTab === 'all' || 
      invoiceTab === 'draft' && invoice.status === 'draft' ||
      invoiceTab === 'pending' && invoice.status === 'pending' ||
      invoiceTab === 'paid' && invoice.status === 'paid' ||
      invoiceTab === 'overdue' && (invoice.status === 'pending' && new Date(invoice.dueDate) < new Date());
    
    const searchLower = invoiceSearchTerm.toLowerCase();
    const matchesSearch = 
      !invoiceSearchTerm ||
      invoice.invoiceNumber.toLowerCase().includes(searchLower) ||
      getClientName(invoice.clientId).toLowerCase().includes(searchLower);
    
    return matchesTab && matchesSearch;
  });
  
  // Determine status class for styling
  const getStatusClass = (status: string, dueDate: string): string => {
    if (status === 'paid') return 'bg-green-500/20 text-green-400';
    if (status === 'draft') return 'bg-gray-500/20 text-gray-400';
    
    const due = new Date(dueDate);
    const today = new Date();
    if (due < today) return 'bg-red-500/20 text-red-400';
    
    const daysRemaining = Math.ceil((due.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
    if (daysRemaining < 3) return 'bg-yellow-500/20 text-yellow-400';
    return 'bg-blue-500/20 text-blue-400';
  };

  // Calculate the totals for the invoice statistics cards
  const invoiceStats = {
    total: filteredInvoices.reduce((sum: number, inv: Invoice) => sum + parseFloat(inv.total.toString()), 0),
    paid: filteredInvoices
      .filter((inv: Invoice) => inv.status === 'paid')
      .reduce((sum: number, inv: Invoice) => sum + parseFloat(inv.total.toString()), 0),
    pending: filteredInvoices
      .filter((inv: Invoice) => inv.status === 'pending')
      .reduce((sum: number, inv: Invoice) => sum + parseFloat(inv.total.toString()), 0),
    overdue: filteredInvoices
      .filter((inv: Invoice) => 
        inv.status === 'pending' && new Date(inv.dueDate) < new Date()
      )
      .reduce((sum: number, inv: Invoice) => sum + parseFloat(inv.total.toString()), 0)
  };

  // === TIMESHEET SECTION ===
  const { 
    timeEntries = [] as TimeEntry[], 
    isLoading: timeEntriesLoading,
    formatDuration,
    formatDate,
    createTimeEntry,
    isFormOpen,
    toggleForm
  } = useTimeEntries();

  // Timesheet state variables
  const [timeView, setTimeView] = useState<'weekly' | 'list' | 'calendar' | 'chart'>('list');
  const [timeSearchTerm, setTimeSearchTerm] = useState<string>('');
  const [formData, setFormData] = useState({
    projectId: '1',
    date: new Date().toISOString().split('T')[0],
    duration: '',
    notes: ''
  });

  // Get project name from ID
  const getProjectName = (projectId: number | null): string => {
    if (!projectId) return 'No Project';
    const project = projects.find((p: Project) => p.id === projectId);
    return project ? project.name : `Project #${projectId}`;
  };

  // Calculate the total hours and earnings for display
  const timeStats = {
    totalHours: (timeEntries as TimeEntry[]).reduce((sum: number, entry: TimeEntry) => 
      sum + (entry.duration || 0), 0) / 3600,

    totalEarnings: (timeEntries as TimeEntry[]).reduce((sum: number, entry: TimeEntry) => {
      const hours = (entry.duration || 0) / 3600;
      const rate = entry.hourlyRate ? parseFloat(entry.hourlyRate.toString()) : 0;
      return sum + (hours * rate);
    }, 0),

    thisWeekHours: (timeEntries as TimeEntry[]).filter((entry: TimeEntry) => {
      const entryDate = new Date(entry.startTime);
      const today = new Date();
      const firstDayOfWeek = new Date(today);
      firstDayOfWeek.setDate(today.getDate() - today.getDay());
      firstDayOfWeek.setHours(0, 0, 0, 0);
      return entryDate >= firstDayOfWeek;
    }).reduce((sum: number, entry: TimeEntry) => sum + (entry.duration || 0), 0) / 3600,

    thisMonthHours: (timeEntries as TimeEntry[]).filter((entry: TimeEntry) => {
      const entryDate = new Date(entry.startTime);
      const today = new Date();
      const firstDayOfMonth = new Date(today.getFullYear(), today.getMonth(), 1);
      return entryDate >= firstDayOfMonth;
    }).reduce((sum: number, entry: TimeEntry) => sum + (entry.duration || 0), 0) / 3600
  };

  // Filter time entries based on search term
  const filteredEntries = (timeEntries as TimeEntry[]).filter((entry: TimeEntry) => {
    const searchLower = timeSearchTerm.toLowerCase();
    const projectName = getProjectName(entry.projectId);

    return !timeSearchTerm || 
      projectName.toLowerCase().includes(searchLower) ||
      (entry.notes && entry.notes.toLowerCase().includes(searchLower));
  });

  // Calculate the total cost based on duration and hourly rate
  const calculateCost = (seconds: number, rate: string): string => {
    const hours = seconds / 3600;
    const hourlyRate = parseFloat(rate);
    return (hours * hourlyRate).toFixed(2);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    const startTime = new Date(formData.date + 'T09:00:00');
    const endTime = new Date(formData.date + 'T17:00:00');

    const durationParts = formData.duration.split(':');
    const hours = parseInt(durationParts[0] || '0');
    const minutes = parseInt(durationParts[1] || '0');
    const durationInSeconds = (hours * 3600) + (minutes * 60);

    const timeEntry = {
      userId: 1,
      projectId: Number(formData.projectId),
      startTime: startTime,
      endTime: endTime,
      duration: durationInSeconds,
      notes: formData.notes || '',
      hourlyRate: "65.00"
    };

    createTimeEntry(timeEntry, {
      onSuccess: () => {
        toggleForm();
        setFormData({
          projectId: '1',
          date: new Date().toISOString().split('T')[0],
          duration: '',
          notes: ''
        });
        toast({
          title: "Time entry saved",
          description: "Your time entry has been added successfully.",
          variant: "default"
        });
      },
      onError: (error: any) => {
        console.error('Failed to create time entry:', error);
        toast({
          title: "Error",
          description: error instanceof Error ? error.message : "There was a problem saving your time entry.",
          variant: "destructive"
        });
      }
    });
  };

  return (
    <div className="container mx-auto max-w-6xl px-4 pb-24 pt-8">
      <PageTitle 
        title="Financial Management" 
        subtitle="Manage your invoices and time entries in one place"
        icon="fa-money-bill-wave"
      />

      {/* Main section toggle */}
      <div className="flex justify-center mb-8">
        <div className="bg-gradient-to-r from-space-900/80 to-space-800/80 backdrop-blur-lg p-1.5 rounded-full inline-flex border border-space-700/50 shadow-glow-lg">
          <button
            onClick={() => setActiveSection('invoices')}
            className={`px-8 py-3 rounded-full text-sm font-medium transition-all duration-300 relative overflow-hidden group ${
              activeSection === 'invoices' 
                ? 'bg-gradient-to-r from-electric to-cyan text-white shadow-glow-md' 
                : 'text-gray-300 hover:text-white hover:bg-space-800/50'
            }`}
          >
            <i className={`fas fa-file-invoice-dollar mr-2 ${activeSection === 'invoices' ? 'text-white' : ''}`}></i>
            <span className="font-semibold">Invoices</span>
          </button>
          <button
            onClick={() => setActiveSection('timesheet')}
            className={`px-8 py-3 rounded-full text-sm font-medium transition-all duration-300 relative overflow-hidden group ${
              activeSection === 'timesheet' 
                ? 'bg-gradient-to-r from-electric to-cyan text-white shadow-glow-md' 
                : 'text-gray-300 hover:text-white hover:bg-space-800/50'
            }`}
          >
            <i className={`fas fa-clock mr-2 ${activeSection === 'timesheet' ? 'text-white' : ''}`}></i>
            <span className="font-semibold">Timesheets</span>
          </button>
        </div>
      </div>

      {/* INVOICES SECTION */}
      {activeSection === 'invoices' && (
        <>
          {/* Invoice Statistics Cards */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
            <GlassCard className="p-6">
              <div className="text-sm uppercase tracking-wider text-gray-400 mb-2 font-medium">Total Value</div>
              <div className="text-3xl font-bold text-white mb-1">${invoiceStats.total.toFixed(2)}</div>
              <div className="text-sm text-gray-400">{filteredInvoices.length} invoices</div>
            </GlassCard>
            
            <GlassCard className="p-6">
              <div className="text-sm uppercase tracking-wider text-gray-400 mb-2 font-medium">Paid</div>
              <div className="text-3xl font-bold text-green-400 mb-1">${invoiceStats.paid.toFixed(2)}</div>
              <div className="text-sm text-gray-400">
                {filteredInvoices.filter((inv: Invoice) => inv.status === 'paid').length} invoices
              </div>
            </GlassCard>
            
            <GlassCard className="p-6">
              <div className="text-sm uppercase tracking-wider text-gray-400 mb-2 font-medium">Pending</div>
              <div className="text-3xl font-bold text-blue-400 mb-1">${invoiceStats.pending.toFixed(2)}</div>
              <div className="text-sm text-gray-400">
                {filteredInvoices.filter((inv: Invoice) => inv.status === 'pending').length} invoices
              </div>
            </GlassCard>
            
            <GlassCard className="p-6">
              <div className="text-sm uppercase tracking-wider text-gray-400 mb-2 font-medium">Overdue</div>
              <div className="text-3xl font-bold text-red-400 mb-1">${invoiceStats.overdue.toFixed(2)}</div>
              <div className="text-sm text-gray-400">
                {filteredInvoices.filter((inv: Invoice) => 
                  inv.status === 'pending' && new Date(inv.dueDate) < new Date()
                ).length} invoices
              </div>
            </GlassCard>
          </div>
          
          {/* Invoice Content */}
          <GlassCard className="p-5">
            <div className="flex flex-wrap justify-between items-center mb-6 gap-4">
              <div className="flex space-x-1 bg-space-800/50 rounded-lg p-1 shadow-inner">
                <button
                  onClick={() => setInvoiceTab('all')}
                  className={`px-5 py-2 text-sm font-medium rounded-md transition-all duration-200 ${
                    invoiceTab === 'all' 
                      ? 'bg-electric text-white shadow-md' 
                      : 'text-gray-300 hover:bg-space-700/70 hover:text-white'
                  }`}
                >
                  All
                </button>
                <button
                  onClick={() => setInvoiceTab('draft')}
                  className={`px-5 py-2 text-sm font-medium rounded-md transition-all duration-200 ${
                    invoiceTab === 'draft' 
                      ? 'bg-gray-500/30 text-gray-300 shadow-md' 
                      : 'text-gray-300 hover:bg-space-700/70 hover:text-white'
                  }`}
                >
                  Draft
                </button>
                <button
                  onClick={() => setInvoiceTab('pending')}
                  className={`px-5 py-2 text-sm font-medium rounded-md transition-all duration-200 ${
                    invoiceTab === 'pending' 
                      ? 'bg-blue-500/30 text-blue-400 shadow-md' 
                      : 'text-gray-300 hover:bg-space-700/70 hover:text-white'
                  }`}
                >
                  Pending
                </button>
                <button
                  onClick={() => setInvoiceTab('paid')}
                  className={`px-5 py-2 text-sm font-medium rounded-md transition-all duration-200 ${
                    invoiceTab === 'paid' 
                      ? 'bg-green-500/30 text-green-400 shadow-md' 
                      : 'text-gray-300 hover:bg-space-700/70 hover:text-white'
                  }`}
                >
                  Paid
                </button>
              </div>
              
              <div className="flex space-x-3">
                <input 
                  type="text"
                  placeholder="Search invoices..."
                  value={invoiceSearchTerm}
                  onChange={(e) => setInvoiceSearchTerm(e.target.value)}
                  className="bg-space-800/80 backdrop-blur-sm border border-space-700 px-4 py-2.5 rounded-lg text-sm text-white w-72 focus:outline-none focus:border-electric"
                />
                <button 
                  onClick={() => {
                    openCreateModal();
                    toast({
                      title: "New Invoice",
                      description: "Please enter the invoice details in the form.",
                      variant: "default"
                    });
                  }}
                  className="bg-gradient-to-r from-electric to-cyan text-white px-6 py-2.5 text-sm rounded-lg font-medium"
                >
                  <i className="fas fa-plus mr-2"></i>
                  New Invoice
                </button>
              </div>
            </div>
            
            {/* Invoice List */}
            {invoicesLoading ? (
              <div className="flex justify-center p-10">
                <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-r-2 border-electric"></div>
              </div>
            ) : filteredInvoices.length === 0 ? (
              <div className="py-12 px-6 text-center">
                <h3 className="text-lg font-medium text-white mb-2">No invoices found</h3>
                <p className="text-gray-400">No invoices match your current filters or search criteria.</p>
              </div>
            ) : (
              <div className="overflow-x-auto rounded-lg">
                <table className="w-full">
                  <thead className="text-left bg-space-800/70">
                    <tr>
                      <th className="px-4 py-3 text-xs text-gray-300 font-medium tracking-wider uppercase">Invoice #</th>
                      <th className="px-4 py-3 text-xs text-gray-300 font-medium tracking-wider uppercase">Client</th>
                      <th className="px-4 py-3 text-xs text-gray-300 font-medium tracking-wider uppercase">Issue Date</th>
                      <th className="px-4 py-3 text-xs text-gray-300 font-medium tracking-wider uppercase">Due Date</th>
                      <th className="px-4 py-3 text-xs text-gray-300 font-medium tracking-wider uppercase">Status</th>
                      <th className="px-4 py-3 text-xs text-gray-300 font-medium tracking-wider uppercase text-right">Amount</th>
                      <th className="px-4 py-3 text-xs text-gray-300 font-medium tracking-wider uppercase text-center">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-700/30">
                    {filteredInvoices.map((invoice: Invoice) => (
                      <tr 
                        key={invoice.id} 
                        className="hover:bg-space-800/50 transition-all duration-150 group"
                      >
                        <td className="px-4 py-4 text-sm text-white font-medium">
                          {invoice.invoiceNumber}
                        </td>
                        <td className="px-4 py-4 text-sm">
                          <div className="font-medium text-white">{getClientName(invoice.clientId)}</div>
                        </td>
                        <td className="px-4 py-4 text-sm text-gray-300">
                          {new Date(invoice.issueDate).toLocaleDateString()}
                        </td>
                        <td className="px-4 py-4 text-sm text-gray-300">
                          {new Date(invoice.dueDate).toLocaleDateString()}
                        </td>
                        <td className="px-4 py-4">
                          <span 
                            className={`inline-block px-3 py-1 text-xs rounded-full ${
                              getStatusClass(invoice.status || 'pending', invoice.dueDate.toString())
                            }`}
                          >
                            {getStatusText(invoice.status || 'pending')}
                          </span>
                        </td>
                        <td className="px-4 py-4 text-sm text-white text-right font-medium">
                          ${parseFloat(invoice.total.toString()).toFixed(2)}
                        </td>
                        <td className="px-4 py-4">
                          <div className="flex space-x-2 justify-center">
                            <button 
                              className="w-8 h-8 rounded-full bg-space-800/80 hover:bg-space-700 flex items-center justify-center text-electric hover:text-cyan"
                              onClick={() => openDetailModal(invoice)}
                              title="View"
                            >
                              <i className="fas fa-eye"></i>
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </GlassCard>
        </>
      )}
      
      {/* TIMESHEET SECTION */}
      {activeSection === 'timesheet' && (
        <>
          {/* Timesheet Statistics Cards */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-6">
            <GlassCard className="p-5">
              <div className="text-xs text-gray-400 mb-1">Total Hours</div>
              <div className="text-2xl font-bold text-white">{timeStats.totalHours.toFixed(1)} hrs</div>
              <div className="text-xs text-gray-400 mt-2">{(timeEntries as TimeEntry[]).length} time entries</div>
            </GlassCard>
            
            <GlassCard className="p-5">
              <div className="text-xs text-gray-400 mb-1">Total Earnings</div>
              <div className="text-2xl font-bold text-green-400">${timeStats.totalEarnings.toFixed(2)}</div>
              <div className="text-xs text-gray-400 mt-2">Based on hourly rates</div>
            </GlassCard>
            
            <GlassCard className="p-5">
              <div className="text-xs text-gray-400 mb-1">This Week</div>
              <div className="text-2xl font-bold text-cyan">{timeStats.thisWeekHours.toFixed(1)} hrs</div>
              <div className="text-xs text-gray-400 mt-2">Since Sunday</div>
            </GlassCard>
            
            <GlassCard className="p-5">
              <div className="text-xs text-gray-400 mb-1">This Month</div>
              <div className="text-2xl font-bold text-purple-400">{timeStats.thisMonthHours.toFixed(1)} hrs</div>
              <div className="text-xs text-gray-400 mt-2">{new Date().toLocaleString('default', { month: 'long' })}</div>
            </GlassCard>
          </div>
          
          {/* Timesheet Content */}
          <GlassCard className="p-5">
            <div className="flex flex-wrap justify-between items-center mb-6 gap-4">
              <div className="flex space-x-1">
                <button
                  onClick={() => setTimeView('list')}
                  className={`px-4 py-2 text-sm rounded-md ${
                    timeView === 'list' 
                      ? 'bg-electric/20 text-electric' 
                      : 'text-gray-400 hover:bg-space-800/50'
                  }`}
                >
                  <i className="fas fa-list-ul mr-2"></i>
                  List View
                </button>
              </div>
              
              <div className="flex space-x-2">
                <input 
                  type="text"
                  placeholder="Search time entries..."
                  value={timeSearchTerm}
                  onChange={(e) => setTimeSearchTerm(e.target.value)}
                  className="bg-space-800/50 border border-space-700 px-3 py-2 rounded-md text-sm text-white w-60 focus:outline-none focus:border-electric"
                />
                <button 
                  onClick={() => toggleForm()}
                  className="bg-electric/80 hover:bg-electric text-white px-4 py-2 text-sm rounded-md font-medium"
                >
                  <i className="fas fa-plus mr-1"></i> Add Time
                </button>
              </div>
            </div>
            
            {/* Add Time Entry Form */}
            {isFormOpen && (
              <form onSubmit={handleSubmit} className="bg-space-800/50 rounded-lg p-4 mb-4">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
                  <div>
                    <label className="block text-xs text-gray-400 mb-1">Project</label>
                    <select 
                      name="projectId"
                      value={formData.projectId}
                      onChange={handleChange}
                      className="w-full bg-space-800 border border-gray-700 rounded p-2 text-sm text-white"
                    >
                      {Array.isArray(projects) && projects.length > 0 ? (
                        projects.map((project: Project) => (
                          <option key={project.id} value={project.id}>{project.name}</option>
                        ))
                      ) : (
                        <option value="1">Default Project</option>
                      )}
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs text-gray-400 mb-1">Date</label>
                    <input 
                      type="date" 
                      name="date"
                      value={formData.date}
                      onChange={handleChange}
                      className="w-full bg-space-800 border border-gray-700 rounded p-2 text-sm text-white" 
                    />
                  </div>
                  <div>
                    <label className="block text-xs text-gray-400 mb-1">Duration (HH:MM)</label>
                    <input 
                      type="text" 
                      name="duration"
                      value={formData.duration}
                      onChange={handleChange}
                      placeholder="e.g. 02:30" 
                      className="w-full bg-space-800 border border-gray-700 rounded p-2 text-sm text-white" 
                    />
                  </div>
                </div>
                
                <textarea
                  name="notes"
                  value={formData.notes}
                  onChange={handleChange}
                  className="w-full bg-space-800 border border-gray-700 rounded p-2 text-sm text-white mb-4"
                  placeholder="Notes about work completed"
                  rows={3}
                ></textarea>
                
                <div className="flex space-x-2 justify-end">
                  <button 
                    type="button"
                    onClick={() => toggleForm()}
                    className="bg-space-800 text-white px-4 py-2 rounded hover:bg-space-700"
                  >
                    Cancel
                  </button>
                  <button 
                    type="submit"
                    className="bg-electric text-white px-4 py-2 rounded hover:bg-electric/80"
                  >
                    Add Time Entry
                  </button>
                </div>
              </form>
            )}
            
            {/* Time Entries List View */}
            {timeEntriesLoading ? (
              <div className="flex justify-center p-10">
                <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-cyan"></div>
              </div>
            ) : filteredEntries.length === 0 ? (
              <div className="p-6 text-center">
                <p className="text-gray-400">No time entries found matching your criteria.</p>
                <p className="text-xs text-gray-500 mt-1">Try changing your search or add a new time entry.</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead className="text-left">
                    <tr className="border-b border-gray-700/50">
                      <th className="px-4 py-2 text-xs text-gray-400 font-medium">DATE</th>
                      <th className="px-4 py-2 text-xs text-gray-400 font-medium">PROJECT</th>
                      <th className="px-4 py-2 text-xs text-gray-400 font-medium">DESCRIPTION</th>
                      <th className="px-4 py-2 text-xs text-gray-400 font-medium">DURATION</th>
                      <th className="px-4 py-2 text-xs text-gray-400 font-medium">RATE</th>
                      <th className="px-4 py-2 text-xs text-gray-400 font-medium text-right">COST</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-700/30">
                    {filteredEntries.map((entry: TimeEntry) => (
                      <tr key={entry.id} className="hover:bg-space-800/50 transition-colors">
                        <td className="px-4 py-3 text-sm text-gray-300">
                          {formatDate ? formatDate(entry.startTime.toISOString()) : new Date(entry.startTime).toLocaleDateString()}
                        </td>
                        <td className="px-4 py-3 text-sm">
                          <div className="font-medium text-white">{getProjectName(entry.projectId)}</div>
                        </td>
                        <td className="px-4 py-3 text-sm text-gray-300">
                          {entry.notes || 'No description'}
                        </td>
                        <td className="px-4 py-3 text-sm text-white">
                          {formatDuration ? formatDuration(entry.duration || 0) : `${((entry.duration || 0) / 3600).toFixed(1)}h`}
                        </td>
                        <td className="px-4 py-3 text-sm text-gray-300">
                          ${entry.hourlyRate ? parseFloat(entry.hourlyRate.toString()).toFixed(2) : '0.00'}/hr
                        </td>
                        <td className="px-4 py-3 text-sm text-white text-right font-medium">
                          ${calculateCost(entry.duration || 0, entry.hourlyRate?.toString() || '0')}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </GlassCard>
        </>
      )}
    </div>
  );
};

export default CombinedPage;
