import { FC, useState, useEffect, useRef, useCallback, useMemo, memo } from 'react';
import { useIsMobile } from '@/hooks/use-mobile';
import { Link } from 'wouter';
import { APP_NAME, APP_VERSION } from '@/lib/constants';
import { useAuth } from '@/hooks/useAuth';
import { toast } from '@/hooks/use-toast';
// Import styles directly - CSS module is applied globally
import './scrollbar-styles.module.css';
import { Button } from '@/components/ui/button';
import { 
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger 
} from '@/components/ui/dropdown-menu';
import {
  User, 
  Settings, 
  LogOut, 
  Bell,
  HelpCircle,
  ChevronDown,
  Calendar,
  Clock,
  Cloud,
  CloudLightning,
  CloudDrizzle,
  CloudRain,
  CloudSnow,
  Sun
} from 'lucide-react';
import str8BuildLogo from '@/assets/str8-build-logo.png';

// Adjust the type to match the User type from useAuth
interface UserAvatarProps {
  user: {
    username?: string;
    profileImageUrl?: string | null;
  } | null;
  className?: string;
}

const UserAvatar = memo(({ user, className = '' }: UserAvatarProps) => (
  <div className={`relative ${className}`}>
    {user?.profileImageUrl ? (
      <div className="relative">
        <div className="absolute -inset-0.5 bg-gradient-to-r from-cyan-400/40 to-green-400/40 rounded-full blur opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
        <img 
          src={user.profileImageUrl} 
          alt={user?.username || "User"} 
          className="relative h-8 w-8 rounded-full object-cover ring-2 ring-cyan-400/30 group-hover:ring-green-400/50 transition-all duration-300 group-hover:scale-105"
          loading="lazy"
          width={32}
          height={32}
        />
      </div>
    ) : (
      <div className="relative">
        <div className="absolute -inset-0.5 bg-gradient-to-r from-cyan-400/40 to-green-400/40 rounded-full blur opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
        <div className="relative h-8 w-8 rounded-full bg-gradient-to-br from-blue-500 to-cyan-400 flex items-center justify-center text-white ring-2 ring-cyan-400/30 group-hover:ring-green-400/50 transition-all duration-300 group-hover:scale-105">
          <span className="font-medium" aria-hidden="true">
            {user?.username ? user.username.charAt(0).toUpperCase() : 'U'}
          </span>
        </div>
      </div>
    )}
  </div>
));

const Header: FC = () => {
  const { user, logout } = useAuth();
  const [currentTime, setCurrentTime] = useState(new Date());
  const [weatherIcon, setWeatherIcon] = useState<string>('Sun');
  const [location, setLocation] = useState<string>('');
  const [showLocationInput, setShowLocationInput] = useState<boolean>(false);
  const [notifications, setNotifications] = useState<Array<{
    id: string;
    title: string;
    message: string;
    time: string;
    read: boolean;
    type: 'info' | 'success' | 'warning' | 'error';
  }>>([{
    id: '1',
    title: 'New Project',
    message: 'Your project "Kitchen Renovation" has been created successfully.',
    time: '10 min ago',
    read: false,
    type: 'success'
  }, {
    id: '2',
    title: 'Timer Alert',
    message: 'Your active timer is approaching 8 hours of work today.',
    time: '1 hour ago',
    read: false,
    type: 'warning'
  }, {
    id: '3',
    title: 'Weather Alert',
    message: 'Weather conditions changing in Wellington. Plan accordingly.',
    time: '3 hours ago',
    read: false,
    type: 'info'
  }]);
  const [showNotifications, setShowNotifications] = useState(false);
  const isMobile = useIsMobile();
  
  // Update the time every minute
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 60000);
    
    return () => clearInterval(timer);
  }, []);
  
  // Weather icon simulation and location detection
  useEffect(() => {
    // Simulate different weather based on time of day for demo purposes
    const hours = new Date().getHours();
    let selectedWeather;
    
    if (hours >= 6 && hours < 12) {
      selectedWeather = 'Sun'; // Morning
    } else if (hours >= 12 && hours < 17) {
      selectedWeather = 'Cloud'; // Afternoon
    } else if (hours >= 17 && hours < 20) {
      selectedWeather = 'CloudDrizzle'; // Evening
    } else {
      selectedWeather = 'CloudLightning'; // Night
    }
    
    setWeatherIcon(selectedWeather);
    
    // Try to get saved location from localStorage
    const savedLocation = localStorage.getItem('userLocation');
    if (savedLocation) {
      setLocation(savedLocation);
    } else {
      // Set a default location
      setLocation('Wellington, NZ');
    }
  }, []);
  
  const formatDate = (date: Date): string => {
    const options: Intl.DateTimeFormatOptions = { 
      weekday: 'short',
      year: 'numeric', 
      month: 'short', 
      day: 'numeric'
    };
    return date.toLocaleDateString('en-NZ', options);
  };
  
  const formatTime = (date: Date): string => {
    const options: Intl.DateTimeFormatOptions = { 
      hour: '2-digit', 
      minute: '2-digit',
      hour12: true
    };
    return date.toLocaleTimeString('en-NZ', options);
  };
  
  const handleLogout = useCallback(async () => {
    try {
      await logout();
    } catch (error) {
      console.error('Logout failed:', error);
      toast({
        title: "Logout Failed",
        description: "There was an error signing out. Please try again.",
        variant: "destructive",
      });
    }
  }, [logout]);
  
  return (
    <header className="sticky top-0 z-40 bg-gradient-to-b from-space-950 to-space-900/90 backdrop-blur-xl border-b border-cyan-800/30 shadow-2xl shadow-cyan-900/20 pb-2">
      <div className="px-2 sm:px-4 md:container mx-auto pt-2 flex flex-col space-y-2">
        {/* Logo and brand section */}
        <div className="flex justify-between items-center relative">
          <div className="absolute inset-0 bg-gradient-to-r from-cyan-900/5 via-transparent to-blue-900/5 rounded-xl opacity-70"></div>
          <Link href="/" className="flex items-center space-x-2 relative group">
            <div className="absolute -inset-2 bg-gradient-to-r from-cyan-400/10 to-cyan-500/0 rounded-xl opacity-0 group-hover:opacity-100 transition-all duration-500 blur-sm"></div>
            <div className="relative overflow-hidden rounded-xl p-1 transition-all duration-300 group-hover:scale-[1.02]">
              <img 
                src={str8BuildLogo} 
                alt="STR8 BUILD Logo" 
                className="h-10 md:h-12 w-auto drop-shadow-md" 
              />
              <div className="absolute inset-0 bg-gradient-to-tr from-cyan-500/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
            </div>
            <div className="relative">
              <span className="bg-gradient-to-r from-blue-800 to-cyan-900 text-cyan-100 text-xs px-2 py-0.5 rounded-full shadow-inner shadow-cyan-800/30 border border-cyan-700/30">
                v{APP_VERSION}
              </span>
              <div className="absolute -inset-1 bg-gradient-to-r from-cyan-400/20 to-blue-500/20 rounded-full blur-sm opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
            </div>
          </Link>
          
          {/* User Controls */}
          <div className="flex items-center space-x-3">
            {/* Notification Bell */}
            <div className="relative group">
              <div className="absolute -inset-1 bg-gradient-to-r from-cyan-400/20 to-blue-500/20 rounded-full blur-sm opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="bg-gradient-to-br from-space-800/80 to-space-900/90 hover:from-space-700/90 hover:to-space-800/90 text-cyan-100 rounded-full w-9 h-9 flex items-center justify-center border border-cyan-500/30 shadow-md shadow-cyan-900/20 transition-all duration-300 hover:shadow-cyan-700/20 hover:border-cyan-400/40 relative p-0"
                  >
                    <div className="absolute inset-0 bg-gradient-to-tr from-cyan-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 rounded-full"></div>
                    <Bell className="h-4 w-4 text-cyan-400 group-hover:text-cyan-300 transition-colors duration-300" />
                    {notifications.filter(n => !n.read).length > 0 && (
                      <span className="absolute -top-0.5 -right-0.5 bg-gradient-to-r from-electric to-cyan-500 text-black text-xs font-bold rounded-full min-w-[16px] h-4 flex items-center justify-center px-[3px] border border-cyan-400/30 shadow-sm shadow-cyan-900/50 transform scale-90 group-hover:scale-100 transition-transform duration-300">
                        {notifications.filter(n => !n.read).length}
                      </span>
                    )}
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent
                  align="end"
                  className="w-80 bg-gradient-to-br from-space-800 to-space-900 border border-cyan-500/20 shadow-xl shadow-cyan-900/30 text-cyan-100 max-h-[400px] overflow-hidden"
                >
                  <div className="flex items-center justify-between p-3 border-b border-cyan-500/20">
                    <DropdownMenuLabel className="text-cyan-400 mb-0 pb-0">Notifications</DropdownMenuLabel>
                    {notifications.filter(n => !n.read).length > 0 && (
                      <Button 
                        variant="ghost" 
                        size="sm" 
                        className="text-xs text-cyan-300 hover:text-cyan-100 bg-transparent hover:bg-cyan-800/20 h-auto py-1 px-2"
                        onClick={() => {
                          setNotifications(notifications.map(n => ({ ...n, read: true })));
                        }}
                      >
                        Mark all as read
                      </Button>
                    )}
                  </div>
                  
                  <div className="max-h-[300px] overflow-y-auto">
                    {notifications.length === 0 ? (
                      <div className="p-4 text-center text-gray-400">
                        <p>No notifications</p>
                      </div>
                    ) : (
                      notifications.map((notification) => {
                        // Map notification type to icon and color
                        const getTypeStyles = (type: string) => {
                          switch(type) {
                            case 'success':
                              return { bg: 'bg-green-500/10', border: 'border-green-500/30', icon: <div className="text-green-400 font-bold">✓</div> };
                            case 'warning':
                              return { bg: 'bg-amber-500/10', border: 'border-amber-500/30', icon: <div className="text-amber-400 font-bold">⚠</div> };
                            case 'error':
                              return { bg: 'bg-red-500/10', border: 'border-red-500/30', icon: <div className="text-red-400 font-bold">×</div> };
                            default:
                              return { bg: 'bg-cyan-500/10', border: 'border-cyan-500/30', icon: <div className="text-cyan-400 font-bold">i</div> };
                          }
                        };
                        
                        const styles = getTypeStyles(notification.type);
                        
                        return (
                          <div key={notification.id} className={`p-3 border-b border-cyan-800/30 hover:bg-cyan-800/20 transition-colors duration-200 cursor-pointer ${!notification.read ? 'bg-space-800/50' : ''}`}>
                            <div className="flex items-start gap-3">
                              <div className={`mt-0.5 flex-shrink-0 w-6 h-6 rounded-full ${styles.bg} ${styles.border} flex items-center justify-center`}>
                                {styles.icon}
                              </div>
                              <div className="flex-1 min-w-0">
                                <div className="flex items-start justify-between gap-2">
                                  <h4 className={`text-sm font-medium truncate ${!notification.read ? 'text-cyan-100' : 'text-cyan-300'}`}>
                                    {notification.title}
                                  </h4>
                                  <span className="text-xs text-gray-400 whitespace-nowrap">{notification.time}</span>
                                </div>
                                <p className="text-xs mt-1 text-gray-400">{notification.message}</p>
                              </div>
                            </div>
                            
                            {!notification.read && (
                              <div className="flex justify-end mt-2">
                                <Button 
                                  variant="ghost" 
                                  size="sm" 
                                  className="text-xs text-cyan-400 hover:text-cyan-100 bg-transparent hover:bg-cyan-800/20 h-auto py-1 px-2"
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    setNotifications(notifications.map(n => 
                                      n.id === notification.id ? { ...n, read: true } : n
                                    ));
                                  }}
                                >
                                  Mark as read
                                </Button>
                              </div>
                            )}
                          </div>
                        );
                      })
                    )}
                  </div>
                  
                  <div className="p-2 border-t border-cyan-500/20">
                    <Button 
                      variant="ghost" 
                      size="sm" 
                      className="w-full text-center justify-center text-sm text-cyan-400 hover:text-cyan-100 hover:bg-cyan-500/10"
                      onClick={() => {}}
                    >
                      View all notifications
                    </Button>
                  </div>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button 
                  variant="ghost" 
                  size="sm" 
                  className="flex items-center space-x-1 bg-gradient-to-br from-space-800/80 to-space-900/90 hover:from-space-700/90 hover:to-space-800/90 text-cyan-100 rounded-full px-3 py-1 border border-cyan-500/30 shadow-md shadow-cyan-900/20 transition-all duration-300 hover:shadow-cyan-700/20 hover:border-cyan-400/40"
                >
                  <UserAvatar user={user as UserAvatarProps['user']} />
                  {!isMobile && (
                    <>
                      <span className="ml-2 text-sm font-medium">{user?.username || 'User'}</span>
                      <ChevronDown className="h-4 w-4 text-cyan-400" />
                    </>
                  )}
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent
                align="end"
                className="w-56 bg-gradient-to-br from-space-800 to-space-900 border border-cyan-500/20 shadow-xl shadow-cyan-900/30 text-cyan-100"
              >
                <DropdownMenuLabel className="text-cyan-400">My Account</DropdownMenuLabel>
                <DropdownMenuSeparator className="bg-cyan-500/20" />
                <DropdownMenuItem 
                  className="hover:bg-cyan-500/10 focus:bg-cyan-500/10 cursor-pointer"
                  onClick={() => {}}
                >
                  <User className="mr-2 h-4 w-4 text-cyan-400" />
                  <span>Profile</span>
                </DropdownMenuItem>
                <DropdownMenuItem 
                  className="hover:bg-cyan-500/10 focus:bg-cyan-500/10 cursor-pointer"
                  onClick={() => {}}
                >
                  <Settings className="mr-2 h-4 w-4 text-cyan-400" />
                  <span>Settings</span>
                </DropdownMenuItem>
                <DropdownMenuItem 
                  className="hover:bg-cyan-500/10 focus:bg-cyan-500/10 cursor-pointer"
                  onClick={() => {}}
                >
                  <HelpCircle className="mr-2 h-4 w-4 text-cyan-400" />
                  <span>Help</span>
                </DropdownMenuItem>
                <DropdownMenuSeparator className="bg-cyan-500/20" />
                <DropdownMenuItem 
                  className="hover:bg-red-500/10 focus:bg-red-500/10 text-red-400 cursor-pointer"
                  onClick={handleLogout}
                >
                  <LogOut className="mr-2 h-4 w-4" />
                  <span>Logout</span>
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </div>
        
        {/* Date, Time, and Weather Section - Hidden on mobile */}
        {!isMobile && (
          <div className="hidden md:flex items-center space-x-2 bg-gradient-to-br from-space-800/70 to-space-900/80 backdrop-blur-md 
            border border-cyan-500/30 rounded-xl px-4 py-2 shadow-lg shadow-cyan-900/30
            transition-all duration-300 hover:shadow-cyan-800/40 hover:border-cyan-400/40 hover:from-space-800/80 hover:to-space-850/90
            relative overflow-hidden group/header before:absolute before:inset-0 before:bg-space-800/5 before:backdrop-blur-[1px] before:opacity-0 before:group-hover/header:opacity-100 before:transition-opacity before:duration-500">
            
            {/* Subtle animated glow effect */}
            {/* Professional gradient background effect with animation */}
            <div className="absolute inset-0 bg-gradient-to-r from-cyan-600/15 via-electric/10 to-blue-500/15 opacity-0 group-hover/header:opacity-100 transition-all duration-700 rounded-xl overflow-hidden">
              <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_120%,rgba(34,211,238,0.1),transparent_60%)] mix-blend-overlay"></div>
              <div className="absolute -inset-0.5 bg-gradient-to-tr from-cyan-500/10 to-transparent blur-sm opacity-0 group-hover/header:opacity-100 transition-all duration-500 delay-100"></div>
              <div className="absolute bottom-0 left-0 right-0 h-[1px] bg-gradient-to-r from-transparent via-cyan-400/40 to-transparent transform translate-y-0.5 opacity-0 group-hover/header:opacity-100 transition-all duration-700 delay-150"></div>
            </div>
            <div className="absolute top-0 left-0 right-0 h-[1px] bg-gradient-to-r from-transparent via-cyan-500/40 to-transparent transform scale-x-95 group-hover/header:scale-x-100 transition-transform duration-500"></div>
            <div className="absolute bottom-0 left-0 right-0 h-[1px] bg-gradient-to-r from-transparent via-cyan-400/20 to-transparent transform scale-x-95 group-hover/header:scale-x-100 transition-transform duration-500 delay-100"></div>
            <div className="absolute top-0 right-0 w-20 h-20 bg-gradient-to-bl from-electric/5 to-transparent opacity-0 group-hover/header:opacity-100 transition-opacity duration-700 blur-md"></div>
            <div className="absolute bottom-0 left-0 w-20 h-20 bg-gradient-to-tr from-cyan-500/5 to-transparent opacity-0 group-hover/header:opacity-100 transition-opacity duration-700 blur-md"></div>
            {/* Date Display */}
            <div className="flex items-center space-x-2 group">
              <div className="p-1.5 rounded-lg bg-gradient-to-br from-cyan-500/20 to-blue-500/10 group-hover:from-cyan-500/30 group-hover:to-blue-500/20 transition-all duration-300 shadow-sm shadow-cyan-500/10 group-hover:shadow-cyan-500/30 relative overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-tr from-cyan-400/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 rounded-lg"></div>
                <Calendar className="h-4 w-4 text-cyan-300 group-hover:text-cyan-200 transition-colors duration-300 relative z-10" />
              </div>
              <div className="flex flex-col">
                <span className="text-xs font-medium text-cyan-300/80">Today</span>
                <span className="text-sm font-semibold bg-gradient-to-r from-cyan-100 to-blue-100 bg-clip-text text-transparent">{formatDate(currentTime)}</span>
              </div>
            </div>
            
            <div className="w-px h-8 bg-gradient-to-b from-cyan-500/10 via-cyan-300/40 to-cyan-500/10 mx-1 group-hover/header:via-cyan-300/60 transition-all duration-500"></div>
            
            {/* Time Display */}
            <div className="flex items-center space-x-2 group">
              <div className="p-1.5 rounded-lg bg-gradient-to-br from-cyan-500/20 to-blue-500/10 group-hover:from-cyan-500/30 group-hover:to-blue-500/20 transition-all duration-300 shadow-sm shadow-cyan-500/10 group-hover:shadow-cyan-500/30 relative overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-tr from-cyan-400/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 rounded-lg"></div>
                <Clock className="h-4 w-4 text-cyan-300 group-hover:text-cyan-200 transition-colors duration-300 relative z-10" />
              </div>
              <div className="flex flex-col">
                <span className="text-xs font-medium text-cyan-300/80">Local Time</span>
                <span className="text-sm font-semibold bg-gradient-to-r from-cyan-100 to-blue-100 bg-clip-text text-transparent">{formatTime(currentTime)}</span>
              </div>
            </div>
            
            <div className="w-px h-8 bg-gradient-to-b from-cyan-500/10 via-cyan-300/40 to-cyan-500/10 mx-1 group-hover/header:via-cyan-300/60 transition-all duration-500"></div>
            
            {/* Weather Display */}
            <div className="flex items-center space-x-2 group">
              <div className="p-1.5 rounded-lg bg-gradient-to-br from-cyan-500/20 to-blue-500/10 group-hover:from-cyan-500/30 group-hover:to-blue-500/20 transition-all duration-300 shadow-sm shadow-cyan-500/10 group-hover:shadow-cyan-500/30 relative overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-tr from-cyan-400/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 rounded-lg"></div>
                {weatherIcon === 'Sun' && <Sun className="h-4 w-4 text-yellow-300" />}
                {weatherIcon === 'Cloud' && <Cloud className="h-4 w-4 text-cyan-300" />}
                {weatherIcon === 'CloudLightning' && <CloudLightning className="h-4 w-4 text-purple-300" />}
                {weatherIcon === 'CloudDrizzle' && <CloudDrizzle className="h-4 w-4 text-cyan-200" />}
                {weatherIcon === 'CloudRain' && <CloudRain className="h-4 w-4 text-blue-300" />}
                {weatherIcon === 'CloudSnow' && <CloudSnow className="h-4 w-4 text-white" />}
                <div className="absolute inset-0 bg-gradient-to-r from-cyan-500/5 to-purple-500/10 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
              </div>
              <div className="flex flex-col">
                <span className="text-xs font-medium text-cyan-300/80">Weather</span>
                <span className="text-sm font-semibold bg-gradient-to-r from-cyan-100 to-blue-100 bg-clip-text text-transparent">
                  {weatherIcon === 'Sun' && 'Sunny'}
                  {weatherIcon === 'Cloud' && 'Cloudy'}
                  {weatherIcon === 'CloudLightning' && 'Stormy'}
                  {weatherIcon === 'CloudDrizzle' && 'Drizzle'}
                  {weatherIcon === 'CloudRain' && 'Rainy'}
                  {weatherIcon === 'CloudSnow' && 'Snowy'}
                </span>
              </div>
            </div>
          </div>
        )}
      </div>
    </header>
  );
};

export default Header;
