import { FC, useState } from 'react';
import { useProjects } from '@/hooks/useProjects';
import { Project } from '@shared/schema';
import ProjectCamera from './ProjectCamera';
import ProjectPhotos from './ProjectPhotos';
import { Dialog, DialogContent } from '@/components/ui/dialog';

const ProjectsList: FC = () => {
  const { projects = [], isLoading, openEditModal } = useProjects();
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [cameraOpen, setCameraOpen] = useState(false);
  const [photosOpen, setPhotosOpen] = useState(false);
  
  // Explicitly type the projects array
  const typedProjects = projects as Project[];

  // Format date for better display
  const formatDate = (dateString?: string) => {
    if (!dateString) return 'N/A';
    const date = new Date(dateString);
    return date.toLocaleDateString('en-NZ', {
      year: 'numeric', 
      month: 'short', 
      day: 'numeric'
    });
  };

  // Calculate days since last activity
  const getLastActiveText = (date?: string): string => {
    if (!date) return 'No activity';
    
    const lastActive = new Date(date);
    const today = new Date();
    const diffTime = today.getTime() - lastActive.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
    
    if (diffDays === 0) return 'Today';
    if (diffDays === 1) return 'Yesterday';
    if (diffDays < 7) return `${diffDays} days ago`;
    if (diffDays < 30) return `${Math.floor(diffDays / 7)} weeks ago`;
    return `${Math.floor(diffDays / 30)} months ago`;
  };

  if (isLoading) {
    return (
      <div className="space-y-4">
        <div className="flex justify-center p-10">
          <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-electric"></div>
        </div>
      </div>
    );
  }

  // Use typed projects array
  const displayProjects = typedProjects;
  
  if (displayProjects.length === 0) {
    return (
      <div className="space-y-2">
        <div className="p-6 text-center bg-space-800/50 rounded-lg">
          <p className="text-gray-400">No projects found.</p>
          <p className="text-xs text-gray-500 mt-1">Add a new project to get started.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Project Camera Dialog */}
      <Dialog open={cameraOpen} onOpenChange={setCameraOpen}>
        <DialogContent className="bg-space-900 border-space-700 p-0 max-w-lg overflow-hidden">
          <ProjectCamera 
            project={selectedProject || undefined} 
            onClose={() => setCameraOpen(false)} 
          />
        </DialogContent>
      </Dialog>

      {/* Project Photos Dialog */}
      <Dialog open={photosOpen} onOpenChange={setPhotosOpen}>
        <DialogContent className="bg-space-900 border-space-700 p-6 max-w-2xl">
          <h3 className="text-white text-lg font-medium mb-4">Project Photos</h3>
          {selectedProject && <ProjectPhotos project={selectedProject} />}
        </DialogContent>
      </Dialog>
      
      {displayProjects.map((project: Project) => (
        <div key={project.id} className="bg-space-900 rounded-lg p-4">
          <div className="flex justify-between items-start mb-2">
            <div>
              <h4 className="text-white font-medium">{project.name}</h4>
              <p className="text-sm text-gray-400">
                {project.clientId ? `Client #${project.clientId}` : 'No client'}
              </p>
            </div>
            <span className="text-xs bg-space-800 px-2 py-1 rounded-md text-cyan">
              {getLastActiveText(project.createdAt ? project.createdAt.toString() : undefined)}
            </span>
          </div>
          
          <div className="mt-4">
            <div className="flex justify-between text-xs text-gray-400 mb-1">
              <span>Progress</span>
              <span>{project.progress || 0}%</span>
            </div>
            <div className="w-full bg-space-800 rounded-full h-2.5">
              <div 
                className="bg-electric h-2.5 rounded-full"
                style={{ width: `${project.progress || 0}%` }}
              ></div>
            </div>
          </div>
          
          <div className="mt-4 flex justify-end space-x-2">
            <button 
              className="text-xs bg-space-800 text-white px-3 py-1.5 rounded hover:bg-space-700 transition-all duration-300"
              onClick={() => console.log('Edit project', project.id)}
            >
              <i className="fas fa-pencil-alt mr-1"></i> Edit
            </button>
            <button 
              className="text-xs bg-space-800 text-white px-3 py-1.5 rounded hover:bg-space-700 transition-all duration-300"
              onClick={() => console.log('Track time for project', project.id)}
            >
              <i className="fas fa-clock mr-1"></i> Time
            </button>
            <button 
              className="text-xs bg-space-800 text-white px-3 py-1.5 rounded hover:bg-space-700 transition-all duration-300 group"
              onClick={() => {
                setSelectedProject(project);
                setPhotosOpen(true);
              }}
            >
              <i className="fas fa-images mr-1 group-hover:text-cyan transition-colors duration-300"></i> Photos
            </button>
            <button 
              className="text-xs bg-space-800 text-white px-3 py-1.5 rounded hover:bg-space-700 transition-all duration-300 group"
              onClick={() => {
                setSelectedProject(project);
                setCameraOpen(true);
              }}
            >
              <i className="fas fa-camera mr-1 group-hover:text-cyan transition-colors duration-300"></i> Camera
            </button>
            <button 
              className="text-xs bg-purple-900 text-cyan px-3 py-1.5 rounded hover:bg-purple-800 btn-glow btn-glow-cyan transition-all duration-300"
              onClick={() => openEditModal(project)}
            >
              View Details
            </button>
          </div>
        </div>
      ))}
    </div>
  );
};

export default ProjectsList;